export default [{"id":4364,"question":"هل يجوز للزوج أن يبتعد عن زوجته أكثر من ستة أشهر لأنه في السعودية وهي في مصر؟","title":"ما الضابط في مدة بُعد المغترب عن زوجته؟","answer":"الجواب: هذا يختلف على حسب الأحوال، قد يضطر إلى الزيادة، وقد ينقص، ما في شيء محدود في السفر، يروى عن عمر أنه كان يحدد للجنود ستة أشهر، ولكن ما عليه دليل واضح، يعني: الإنسان قد يحتاج أكثر من ستة أشهر في طلب الرزق، وقد يكفيه شهران ثلاثة.  على كل حال يراعي المصلحة، يتقي الله ويجتهد، فإذا كان يخشى على أهله لا يغيب ستة أشهر يكون عندهم يعمل عندهم في بلدهم، أو تذهب معه، أو تكون المدة أقل من ستة، شهرين ثلاثة، يتحرى لأنه أعلم بنفسه وأعلم بأهله وأعلم بالخطر، فلا يتحدد بستة أشهر ولا بشهرين ولا بثلاثة، على حسب الأحوال.","link":"https://binbaz.org.sa/fatwas/24641/ما-الضابط-في-مدة-بعد-المغترب-عن-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/البُعد عن الزوجة لأكثر من ستة أشهر.mp3","categories":["غياب وفقدان الزوج"]},{"id":6053,"question":"أنا رجل أعمل في السعودية لمدة ثلاث سنوات، وأنا متزوج في اليمن، والسبب أن علي دين، فهل عليّ شيء من ناحية أهلي؟","title":"طول غربة الزوج عن زوجته لقضاء ما عليه من ديون","answer":"الجواب: إذا كنت تطلب الرزق الحلال لأجل الإنفاق عليهم، وقضاء ديونك؛ فلا حرج عليك -إن شاء الله- ولكن ينبغي أن تجتهد بزيارتهم بين وقت، وآخر، تزورهم، وترجع لعملك بعد ستة أشهر، بعد أربعة أشهر، بعد سبعة أشهر، حسب ما تيسر لك، يكون هذا جمعًا بين المصالح، لا تستمر السنوات الطويلة؛ لأن هذا خطر على أهلك، وعليك أيضًا. فينبغي لك أن تعالج الأمور بأحسن العلاج، فتبقى في البلاد التي تعمل فيها أشهرًا معدودة، خمسة، ستة، سبعة، حسب التيسير، ثم تذهب إلى أهلك، ومعك ما يسرهم من الإعانة، والخير، فتبقى عندهم ما شاء الله، ثم ترجع إلى عملك، وهكذا دواليك؛ حتى يغنيك الله في بلادك. وأما الاستمرار سنوات وأنت في عملك، وتركتهم فهذا فيه خطر عظيم عليك، وعليهم جميعًا، فالذي ينبغي أن لا تطول الغربة إذا مكثت أشهرًا مناسبة خمسة، ستة، سبعة. ويروى عن عمر  أنه وقت للمجاهدين ستة أشهر؛ لأن بعد الستة قد يشق عليه ذلك، ويشق على أهله. فالحاصل: أنه ينبغي للغريب الذي يطلب الرزق أن يجتهد في زيارة أهله في أوقات مناسبة بعد خمسة أشهر، بعد ستة، بعد سبعة، حسب التيسير، ثم يرجع إلى عمله جمعًا بين المصالح.","link":"https://binbaz.org.sa/fatwas/1454/طول-غربة-الزوج-عن-زوجته-لقضاء-ما-عليه-من-ديون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_383.mp3","categories":["غياب وفقدان الزوج"]},{"id":6311,"question":"أنا رجل من غير هذه البلاد، ولي زوجة في بلدي، ولي مدة طويلة عنها، ولي زوجة هنا، وأنا أخاف إذا ذهبت إلى بلدي أخاف على نفسي من العذاب هناك؛ لأني  خارج عن عقيدتهم الفاسدة.","title":"حكم ترك الزوجة مدة طويلة بسبب السفر","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/1890/حكم-ترك-الزوجة-مدة-طويلة-بسبب-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_673.mp3","categories":["غياب وفقدان الزوج"]},{"id":6332,"question":"أنا رجل من غير هذه البلاد، ولي زوجة في بلدي، ولي مدة طويلة عنها، ولي زوجة هنا، وأنا أخاف إذا ذهبت إلى بلدي أخاف على نفسي من العذاب هناك؛ لأني  خارج عن عقيدتهم الفاسدة.","title":"حكم ترك الزوجة مدة طويلة بسبب السفر","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/1890/حكم-ترك-الزوجة-مدة-طويلة-بسبب-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_673.mp3","categories":["غياب وفقدان الزوج"]},{"id":6629,"question":"ما حكم من يغترب عن أهله سنة، وأكثر بسبب ما عليه من ديون، وحقوق للناس، ولا يستطيع السفر بسبب حقوق الناس، أفتونا مأجورين؟","title":"حكم طول غربة الرجل عن أهله لطلب الرزق","answer":"الجواب: لا حرج -إن شاء الله- إذا سافر لطلب الرزق -طلب المعيشة- ويعود على أهله بالرزق الذي يعينه على النفقة عليهم والإحسان إليهم، أو لطلب العلم، أو للجهاد في سبيل الله، فلا حرج ولو طالت المدة، لكن إذا أمكنه أن يرجع إليهم بين وقت، وآخر للزيارة، بين أربعة أشهر، ستة أشهر، أكثر أقل، إذا تمكن من هذا  .. مدة مناسبة، فهذا حسن، وطيب، وينبغي له فعل ذلك؛ تطييبًا للنفوس، وحرصًا على جمع الشمل، وعلى أداء الواجب، وعلى حسم مواد النزاع التي قد تنجم عن الغربة.  أما إذا ما تيسر ذلك؛ فلا حرج، ولكن عليه أن يتابع الرسائل، وإرسال النفقات، وطلب السماح من أهله؛ حتى تطيب النفوس، وحتى يقوى الصبر على أساس حسن.","link":"https://binbaz.org.sa/fatwas/2488/حكم-طول-غربة-الرجل-عن-اهله-لطلب-الرزق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1015.mp3","categories":["غياب وفقدان الزوج"]},{"id":6644,"question":"ما حكم من يغترب عن أهله سنة، وأكثر بسبب ما عليه من ديون، وحقوق للناس، ولا يستطيع السفر بسبب حقوق الناس، أفتونا مأجورين؟","title":"حكم طول غربة الرجل عن أهله لطلب الرزق","answer":"الجواب: لا حرج -إن شاء الله- إذا سافر لطلب الرزق -طلب المعيشة- ويعود على أهله بالرزق الذي يعينه على النفقة عليهم والإحسان إليهم، أو لطلب العلم، أو للجهاد في سبيل الله، فلا حرج ولو طالت المدة، لكن إذا أمكنه أن يرجع إليهم بين وقت، وآخر للزيارة، بين أربعة أشهر، ستة أشهر، أكثر أقل، إذا تمكن من هذا  .. مدة مناسبة، فهذا حسن، وطيب، وينبغي له فعل ذلك؛ تطييبًا للنفوس، وحرصًا على جمع الشمل، وعلى أداء الواجب، وعلى حسم مواد النزاع التي قد تنجم عن الغربة.  أما إذا ما تيسر ذلك؛ فلا حرج، ولكن عليه أن يتابع الرسائل، وإرسال النفقات، وطلب السماح من أهله؛ حتى تطيب النفوس، وحتى يقوى الصبر على أساس حسن.","link":"https://binbaz.org.sa/fatwas/2488/حكم-طول-غربة-الرجل-عن-اهله-لطلب-الرزق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1015.mp3","categories":["غياب وفقدان الزوج"]},{"id":6905,"question":"يوجد رجل يغترب عن زوجته حوالي ثمانية أشهر، وأحيانًا سنة كاملة، مع العلم أن هذه الغربة للبحث عن الرزق، فهل عليه شيء قِبَل زوجته؟","title":"حكم الغياب عن الزوجة ثمانية أشهر فأكثر","answer":"الجواب: لا حرج عليه إذا اغترب لطلب الرزق، أو في طلب العلم، وجعل عند زوجته ما يكفيها، أو وكل من محارمها، وأهلها من يقوم عليها؛ فهذا لا بأس عليه -إن شاء الله- ولا حرج، لكن إذا تيسر له أن تكون الغيبة غير طويلة في هذا الزمان الخطير، وفي هذه الأوقات التي ملئت بالشرور، إذا تيسر له أن تكون الغربة مدة قليلة، كأربعة أشهر، أو ثلاثة أشهر، أو يأتي إليها بين وقت وآخر، ثم يرجع إلى عمله في العطلة التي تمكنه في كل شهر يومين، ثلاث، أو يوم واحد، أقل، أكثر.  ينبغي له أن يحرص حتى لا يكون على المرأة شيء من هذه الغربة، وخطر من هذه الغربة في هذه الأوقات الخطيرة، التي كثر فيها دعاة الشر، ودعاة الفساد، إذا استطاع؛ فليعمل، فإذا لم يستطع؛ فالغربة التي تقارب هذا من ستة أشهر، إلى سنة، لا يضره ذلك إذا ترك لها ما يكفيها عند أهلها، أو عند وكيله الذي هو محرمها، أو ما أشبه ذلك.","link":"https://binbaz.org.sa/fatwas/2833/حكم-الغياب-عن-الزوجة-ثمانية-اشهر-فاكثر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1281.mp3","categories":["غياب وفقدان الزوج"]},{"id":7230,"question":"حاولت استقدام أهلي دون جدوى، حيث أنني لا أستطيع الغياب عنهم أكثر من ستة أشهر شرعًا، فحاولت النزول إلى أهلي، ولكن الكفيل رفض نزولي، هل أنا آثم في غيابي عنهم هذا؟","title":"حكم الغياب عن الأهل أكثر من ستة أشهر","answer":"الجواب:\n\nليس عليك شيء -إن شاء الله- ما دام في طلب الرزق، وطلب الحلال، والحرص على جلب الخير لهم، فأنت على خير إن شاء الله. \n\nوإذا استطعت أن تزورهم بين وقت وآخر، ولو أقل من ستة أشهر وترجع؛ يكون أحسن وأولى، ستة طويلة في هذا العصر، فإذا تيسر أن تزورهم بين ثلاثة أشهر، وأربعة أشهر، ثم ترجع إلى عملك؛ هذا خير وأسلم.","link":"https://binbaz.org.sa/fatwas/3300/حكم-الغياب-عن-الاهل-اكثر-من-ستة-اشهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1625.mp3","categories":["غياب وفقدان الزوج"]},{"id":7554,"question":"هذه رسالة وردتنا من جمهورية مصر العربية يقول: اسمي سعيد إبراهيم من جمهورية مصر العربية وأعمل، هو يعمل في الرياض ومتزوج وله أولاد، يقول: أسأل عن حكم من يترك زوجته قرابة السنة والسنتين في السفر، وإني سمعت أنه لا يجوز للرجل أن يغادر أو يترك أهله أكثر من أربعة شهور، مع العلم أن ظروف العمل لا تسمح للفرد أن يسافر إلا بعد تمام السنة على الأقل، أرجو الإفادة وشكراً لكم؟","title":"اغتراب الزوج عن الزوجة مدة طويلة طلباً للرزق","answer":"الجواب: لا مانع إذا سافر الإنسان لطلب المعيشة، لطلب الرزق، ليعمل ويكتسب للنفقة على أهله، أو سافر لطلب العلم، فلا بأس أن يغيب أكثر من أربعة أشهر وأكثر من ستة أشهر، نعم كان عمر اجتهد رضي الله عنه وأرضاه، كان يأمر الرجل أن لا يغيب أكثر من ستة أشهر إذا أمكنه الرجوع إلى أهله، وهذا من اجتهاده رضي الله عنه وأرضاه، والحرص على عفة الفروج، وعلى سلامة المجتمع من الأخطار، فإذا تيسر له أن يزور أهله بعد ستة أشهر فهذا حسن، وإلا فليس بلازم إذا كان في عمل مباح، أو عمل شرعي مثل طلب العلم، وكذلك طلب الرزق وكسب الحلال لينفق على أهله، فهو في هذا في عمل مهم ولا حرج عليه، ولكن إذا كان يخشى شراً على أهله أو يخشى أن الحالة تسوء بينه وبينهم، فينبغي له أن يلاحظ العودة إليهم سريعاً في الوقت المناسب، ولا يرتبط ارتباطاً طويلاً قد يفضي إلى الفرقة بينه وبين أهله، أو يفضي إلى مضرة عليهم، ولا سيما إذا كان يخاف عليهم من الفساد، فينبغي له أن يلاحظ هذا، بنقلهم معه أو الزيارة التي تكون قريبة لا بعيدة، ويتفق مع من يعمل عندهم على هذا الشيء، وكذلك إذا كان في طلب العلم يحرص على الزيارة في الأوقات المناسبة، كالإجازة الصيفية، أو غير هذا من الأوقات التي يمكن أن يزور فيها حتى يجمع بين مصلحتين؛ مصلحة طلب العلم والعمل، ومصلحة أهله، وزيارتهم وقضاء حاجتهم. نعم.","link":"https://binbaz.org.sa/fatwas/4541/اغتراب-الزوج-عن-الزوجة-مدة-طويلة-طلبا-للرزق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_013/01305.mp3","categories":["غياب وفقدان الزوج"]},{"id":7781,"question":"هذه الرسالة وردتنا من محمد توم محمد موسى سوداني، يقول: أعرفكم بأني من إحدى الدول الشقيقة لكم وهي السودان، يقول: إني حضرت هنا للمملكة مما يقارب ثلاثة أشهر، والكفيل لا يرضى أن أذهب للسودان إلا بعد إكمال السنة، فهل علي في ذلك شيء إذا أكملت السنة عن زوجتي؟","title":"غياب الرجل عن زوجته لطلب العلم أو الاكتساب","answer":"الجواب: لا حرج عليه إن شاء الله في طلب الرزق أو طلب العلم، لا حرج عليه إن شاء الله، له المكاتبة في ذلك وإعطائها حاجاتها الواجبة، يعني: إعطاءها النفقة الواجبة والملاحظة لها في كل شيء، فلا بأس أن يتأخر سنة ونحوها، لا حرج في ذلك، لكن يجب عليه أن يعتني بكل ما يلزم لها من النفقة، وكذلك من يلاحظها هناك من أقاربها من محارمها، هذا هو الواجب عليه، أن يعتني بكل شأنها بالمكاتبة حتى لا ينالها خلل، وحتى لا تتعرض لشيء من السوء، أما إذا كان بالاختيار فالأولى والأفضل ألا يتأخر أكثر من ستة أشهر، إذا تيسر له أن يتصل بها بعد ستة أشهر ويلاحظ حاجاتها فهذا أولى وأحوط، كما يروى عن عمر رضي الله عنه وأرضاه في ذلك، أما إذا لم يتيسر ذلك فلا حرج إن شاء الله في السنة ونحوها وأكثر، إذا كان للعلم النافع أو لأمور الدنيا للمكسب اللازم وطلب الرزق لحاجته إليه. نعم.\nالمقدم: يقول أيضاً: هل هناك قول يقول: المدة بالنسبة للمتزوج ستة أشهر، أفيدوني أثابكم الله؟\nالشيخ: تقدم أنه يروى عن عمر ستة أشهر، وأن هذا من باب المصالح المرسلة؛ لأجل الخوف على المرأة، نعم. والخوف عليه أيضاً هو، قد يحتاج إلى ذلك إلى قضاء وطره، قد تحتاج إلى قضاء وطرها، فإذا سافر إليها بعد ستة أشهر لقضاء الوطر ولتفقد الأحوال فهذا أولى إذا تيسر ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/5107/غياب-الرجل-عن-زوجته-لطلب-العلم-او-الاكتساب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_048/04803.mp3","categories":["غياب وفقدان الزوج"]},{"id":7949,"question":"أيضاً له سؤال أخير يقول: كم من الزمن تبيح الشريعة الإسلامية للرجل أن يغيب عن زوجته -ويقصد الجماع في ذلك- علماً بأن بعض الرجال يغيبون عن زوجاتهم طلباً للرزق خارج أوطانهم؟","title":"حكم الإطالة في الغيبة عن الزوجة","answer":"الجواب: لا نعرف في الشريعة حداً محدوداً في الغيبة، ولكن يروى عن عمر  أنه حدد بستة أشهر فإذا تيسر للزوج ألا يغيب أكثر من ستة أشهر فهذا أولى وأحوط، وإذا غاب أكثر لأجل طلب الرزق أو طلب العلم فلا حرج في ذلك إن شاء الله.\nالمقدم: شكراً لسماحة الشيخ عبد العزيز .","link":"https://binbaz.org.sa/fatwas/5479/حكم-الاطالة-في-الغيبة-عن-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_068/06810.mp3","categories":["غياب وفقدان الزوج"]},{"id":8040,"question":"يقول: ما حكم الإسلام في البعد عن الزوجة لمدة سنة أو سنتين؟","title":"البعد والاغتراب عن الزوجة.. حكمه ومفاسده","answer":"الجواب: لا يجوز للمسلم أن يهجر زوجته من الجماع؛ لأن هذا يضرها، وربما أفضى إلى وقوعها في ما لا تحمد عقباه، فالواجب عليه أن يجامعها بالمعروف، حسب الطاقة والإمكان، وقال بعض أهل العلم: إنه يجب عليه ذلك في كل أربعة أشهر مرة، ولكن ليس ذلك بواضح من جهة الدليل، بل الواجب عليه أن يعاشرها بالمعروف، كما قال الله سبحانه: وَعَاشِرُوهُنَّ بِالْمَعْرُوف [النساء:19]، وقال جل وعلا: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوف [البقرة:228].\nومن المعروف: أن يجامعها ويؤانسها ويخاطبها بالتي هي أحسن، وينفق عليها النفقة اللازمة إلى غير ذلك، وليس من المعروف أن يهجرها هذه المدة الطويلة، فالواجب عليه أن يستبيحها، فإذا سمحت وأباحت فلا حرج، وإلا فالواجب عليه أن يعتني بها وأن يجامعها بالمعروف، حسب الطاقة وبحسب الإمكان، وبحسب ما يراه كافياً ومانعاً من وقوع كل منهما فيما لا يرتضى، فإن الجماع يعفه ويعفها جميعاً، وإهمالها المدة الطويلة فيه خطر عليه وعليها جميعاً، إلا من عذر شرعي كمرض أو غربة يحتاج إليها في طلب العلم، أو في طلب الرزق، أو ما أشبه ذلك من الموانع. نعم.","link":"https://binbaz.org.sa/fatwas/5667/البعد-والاغتراب-عن-الزوجة-حكمه-ومفاسده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08103.mp3","categories":["غياب وفقدان الزوج"]},{"id":8567,"question":"هذه رسالة وردتنا من المستمع (ر. ع. أ) مصري يعمل بالمملكة، يقول: أرجو تبيين حكم الشرع في الرجل الذي يترك امرأته لأجل العمل لمدة ثلاث سنوات، هل له جماعها بعد العودة، أم يلزمه شيء قبل ذلك، أفيدونا أفادكم الله؟","title":"حكم غياب الرجل عن زوجته عدة سنوات","answer":"الجواب: المشروع للمؤمن أن يلاحظ حق الزوجة، وأن يجتهد في الاتصال بها بين وقت وآخر حسب الإمكان؛ لأن طول الغيبة قد تعرضها لشر كثير، وقد تبتلى بمن يريدها على الباطل، فالواجب على الزوج أن يلاحظ هذا، وأن يكون له رجعة إليها بين وقت وآخر، وقد حدد عمر  للجنود ستة أشهر، كما أشارت عليه ابنته حفصة في بعض ذلك، ورأى باجتهاده  وأرضاه أن يكون ذلك ستة أشهر؛ لأن في هذا رفقاً بالإناث ورفقاً بالرجال، وقضاء وطر كل واحد منهما، فينبغي للمؤمن أن يلاحظ هذا، وليس في السنة حد محدود، وليس في الشرع فيما نعلم حد محدود سوى ما جاء عن عمر ، فإذا غاب عن زوجته مدة طويلة من أجل العمل، أو من أجل طلب العلم فلا شيء عليه، إذا لم يستطع ولم يتيسر له المجيء إليها، أما مع القدرة فينبغي له أن لا يطول بل يأتي إليها بين أربعة أشهر.. ثلاثة أشهر.. خمسة أشهر.. ستة أشهر مهما أمكن أن تكون المدة قصيرة ولا سيما في هذه العصور التي فشت فيها الشرور، وضعف فيها الإيمان، وكثر فيها الفساق، فينبغي للمؤمن أن يلاحظ هذا وأن يعجل بالرجوع إلى أهله حتى لا يغيب عنهم إلا مدة غير طويلة، كأشهر ثلاثة.. أو أربعة أشهر أو نحو ذلك على حسب بعد المسافة بينهما، نعم.\nالمقدم: بعض الناس يتراءى لهم أنه بعد غياب مدة طويلة لا يصح له أن يجامع زوجته؛ لأنهم يسمعون ما ينقل من التحديد عن عمر ، ويظنون أن من تأخر بعد هذه المدة لا يصح له ملاقاة زوجته؟\nالشيخ: الجماع لابأس به، متى جاء جامعها، ما دام لم يطلقها فله جماعها متى جاء، سواء بعد سنة أو سنتين أو ستة أشهر أو أكثر أو أقل، فهي زوجته.. هي زوجته ما دام لم يطلقها فهي زوجته متى جاء فهي حلال له ولو لم يعطها شيئاً، فالمقصود أنها زوجته، ولكن على كل حال من طريقة الرجال، ومن كرم الرجال أنه يعطيها تحف.. يعطيها هدايا؛ لأجل طول الغيبة من باب المجاملة، ومن باب تقدير صبرها وثباتها، فالحاصل أنها زوجته. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6646/حكم-غياب-الرجل-عن-زوجته-عدة-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_207/20707.mp3","categories":["غياب وفقدان الزوج"]},{"id":8571,"question":"هذه رسالة وردتنا من المستمع (ر. ع. أ) مصري يعمل بالمملكة، يقول: أرجو تبيين حكم الشرع في الرجل الذي يترك امرأته لأجل العمل لمدة ثلاث سنوات، هل له جماعها بعد العودة، أم يلزمه شيء قبل ذلك، أفيدونا أفادكم الله؟","title":"حكم غياب الرجل عن زوجته عدة سنوات","answer":"الجواب: المشروع للمؤمن أن يلاحظ حق الزوجة، وأن يجتهد في الاتصال بها بين وقت وآخر حسب الإمكان؛ لأن طول الغيبة قد تعرضها لشر كثير، وقد تبتلى بمن يريدها على الباطل، فالواجب على الزوج أن يلاحظ هذا، وأن يكون له رجعة إليها بين وقت وآخر، وقد حدد عمر  للجنود ستة أشهر، كما أشارت عليه ابنته حفصة في بعض ذلك، ورأى باجتهاده  وأرضاه أن يكون ذلك ستة أشهر؛ لأن في هذا رفقاً بالإناث ورفقاً بالرجال، وقضاء وطر كل واحد منهما، فينبغي للمؤمن أن يلاحظ هذا، وليس في السنة حد محدود، وليس في الشرع فيما نعلم حد محدود سوى ما جاء عن عمر ، فإذا غاب عن زوجته مدة طويلة من أجل العمل، أو من أجل طلب العلم فلا شيء عليه، إذا لم يستطع ولم يتيسر له المجيء إليها، أما مع القدرة فينبغي له أن لا يطول بل يأتي إليها بين أربعة أشهر.. ثلاثة أشهر.. خمسة أشهر.. ستة أشهر مهما أمكن أن تكون المدة قصيرة ولا سيما في هذه العصور التي فشت فيها الشرور، وضعف فيها الإيمان، وكثر فيها الفساق، فينبغي للمؤمن أن يلاحظ هذا وأن يعجل بالرجوع إلى أهله حتى لا يغيب عنهم إلا مدة غير طويلة، كأشهر ثلاثة.. أو أربعة أشهر أو نحو ذلك على حسب بعد المسافة بينهما، نعم.\nالمقدم: بعض الناس يتراءى لهم أنه بعد غياب مدة طويلة لا يصح له أن يجامع زوجته؛ لأنهم يسمعون ما ينقل من التحديد عن عمر ، ويظنون أن من تأخر بعد هذه المدة لا يصح له ملاقاة زوجته؟\nالشيخ: الجماع لابأس به، متى جاء جامعها، ما دام لم يطلقها فله جماعها متى جاء، سواء بعد سنة أو سنتين أو ستة أشهر أو أكثر أو أقل، فهي زوجته.. هي زوجته ما دام لم يطلقها فهي زوجته متى جاء فهي حلال له ولو لم يعطها شيئاً، فالمقصود أنها زوجته، ولكن على كل حال من طريقة الرجال، ومن كرم الرجال أنه يعطيها تحف.. يعطيها هدايا؛ لأجل طول الغيبة من باب المجاملة، ومن باب تقدير صبرها وثباتها، فالحاصل أنها زوجته. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6646/حكم-غياب-الرجل-عن-زوجته-عدة-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_207/20707.mp3","categories":["غياب وفقدان الزوج"]},{"id":8659,"question":"الرسالة الثالثة في حلقة هذه الليلة وردتنا من المستمع السيد عبد الحليم عصام ، مصري يعمل في العراق، يقول في رسالته: ما حكم الإسلام في رجل يترك زوجته بحجة السفر للعمل، وقد يظل متغرباً عنها عام أو عامين، وهناك من يترك زوجته ثلاثة أعوام، ولا تستطيع الزوجة أن تمنعه من السفر؛ لأن هذا عيب في العرف السائد، فما هو الحكم في حق الزوجة الضائع دون رضاً منها، وقد يتسبب هذا في نشر الرذيلة في المجتمع حيث يضيع دين المرأة دون رقيب إلا نفسها، فما هو حكم الشرع في ذلك، وكم هي الأيام التي تصبر فيها المرأة عن زوجها، أفتونا جزاكم الله خير؟","title":"الحد الذي يغيب منه الرجل عن زوجته","answer":"الجواب: ليس في هذا أيام معدودة ولا محدودة، ولكن الواجب على الزوج أن يتقي الله في زوجته وألا يغيب عنها غيبة طويلة يكون فيها خطر عليها من جهة الرذيلة، من جهة الفساد الخلقي، ينبغي له أن يلاحظها ويعتني بها، وإذا أمكن أن يكون العمل في البلد التي هي فيه حتى يكون عندها ويبيت عندها يكون هذا هو الأصلح، وإذا كان لم يتيسر ذلك فينبغي له أن يلاحظها بالزيارة لها بين وقت وآخر قريب حتى لا تقع في أمر لا يحمد عقباه، وقد ورد عن عمر  أنه حدد للجنود ستة أشهر، وهذا من باب الاجتهاد منه رضي الله عنه.\nوقد ذكر العلماء أن هذا يختلف، فقد تكون الستة مناسبة وقد يخشى على المرأة في أقل من ذلك، فينبغي للزوج أن يلاحظ حال زوجته وحال البلد التي هي فيه، ومن حولها من الناس، فينبغي له أن يلاحظ سلامتها وأمنها، فإذا كانت الستة طويلة عليها وخطيرة فينبغي له أن لا يطول، بل يتصل بها بين وقت وآخر كالشهر والشهرين أو أقل من ذلك، ومهما أمكن أن يكون قريباً منها فهو الواجب لاسيما في أوقات الخطر مثل هذه الأزمنة؛ لأنه كثر فيها الشر وقل فيها الأمن في غالب البلاد وكثرت فيها الفواحش ولاسيما المرأة إذا كانت وحدها فالخطر عليها عظيم، وإذا كانت عند أهلها المأمونين صار الأمر أقل خطراً وأسلم، فعلى الزوج أن يلاحظ هذه الأمور وأن يتقي الله، وإذا كان ولابد من سفر فليجعلها في محل آمن عند أهلها، أو يكون عندها من المحارم أو النساء من يطمئن إليه حتى يكون ذلك أقرب إلى السلامة.\nوأما حد محدود فليس هناك حد محدود سوى ما روي عن عمر  وأرضاه في ذلك وهو: ستة أشهر، وهذه الستة قد يقوى الزوج على الحضور فيها وقد لا يقوى، قد يكون في حاجة إلى طلب علم، قد يكون في حاجة إلى طلب الرزق ما عنده في بلاده مكسب، وقد لا يتيسر له الستة قد يكون العمل يحتاج إلى أكثر من ستة أشهر ويضطر إلى الزيادة، فينبغي له في هذه الحال أن ينقلها معه إذا أمكن أو يجعلها في محل آمن.\nوالخلاصة: أن الواجب عليه تقوى الله في ذلك، وأن يحرص على سلامة زوجته، وعلى الحيطة في حقها، إما بنقلها معه، وإما بتعجيل السفر إليها بين وقت وآخر وألا يطول، وإما بجعلها في محل آمن عند أهلها أو عند محارم مأمونين يكونون عندها أو تكون عندهم حتى يكون الخطر أقل وحتى تكون السلامة أغلب، والله المستعان.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6801/الحد-الذي-يغيب-منه-الرجل-عن-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21406.mp3","categories":["غياب وفقدان الزوج"]},{"id":8929,"question":"الأخ: أحمد محمد أحمد من جمهورية مصر العربية ويعمل في منطقة الجلة في طريق الحجاز، يسأل عن غياب الرجل عن زوجته، هل هناك مدة محددة وبم تنصحون أولئك الذين يغيبون أكثر من سنة عن زوجاتهم؟","title":"حكم غياب الرجل عن أهله لمدة طويلة","answer":"الجواب: ليس للغياب مدة معلومة، ولم يحدد الشارع عليه الصلاة والسلام لغيبة الرجل عن زوجته مدة معلومة فيما بلغنا، وقد جاء عن عمر  أنه حدد لبعض الجنود ستة أشهر ثم يرجعون إلى نسائهم وهذا من اجتهاده  فيما يتعلق بالغزاة.\nفإذا مكث الرجل عن زوجته ستة أشهر في طلب الرزق أو في طلب العلم ثم رجع إليهم وزارهم شيئاً من الزمن ثم رجع إلى عمله فهذا حسن إن شاء الله وفيه تأس بأمير المؤمنين عمر  وفيه عناية بالأهل ولكن هذا لا يصلح في كل زمان، قد تكون الحاجة ماسة إلى أقل من هذه المدة، فالإنسان ينظر الأصلح ويتأمل فقد تكون زوجته ليس عندها من يقوم بحالها، وقد يخشى عليها من الفتنة، فينبغي له أن لا يبقى عنها ستة أشهر ولا خمسة أشهر بل ينبغي له أن يلاحظها بين وقت وآخر، ما بين شهر أو شهرين أو نحو ذلك أو ينقلها معه إذا استطاع ذلك فإن الوقت تغير والزمان تغير بتغير أهله، فقل بلاد اليوم تؤمن فيه الفتنة على المرأة.\nفالحاصل أن المرأة على خطر بسبب تغير الأحوال وكثرة الشرور وكثرة أهل المعاصي والطامعين في النساء إلا من رحم ربك، فينبغي للمؤمن أن يجتهد في نقل زوجته معه إذا غاب أو يقلل الغيبة وتكون المدة قليلة حتى يرجع إلى أهله ويتفقد أحوالهم ويقضي وطره من أهله ثم يرجع إلى حاجته التي يضطر إليها.\nوالمقصود من هذا كله: العناية بالأهل والحرص على مراعاة أمورهم وشئونهم حتى لا تتخطفهم الشياطين وحتى لا تقع فتنة تكون عاقبتها الطلاق والفرقة. نعم.","link":"https://binbaz.org.sa/fatwas/7086/حكم-غياب-الرجل-عن-اهله-لمدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_143/14304.mp3","categories":["غياب وفقدان الزوج"]},{"id":9300,"question":"وأولى رسائل هذه الحلقة رسالة وردت إلى البرنامج من سائلة تقيم في المدينة المنورة، تقول في رسالتها: أنا امرأة عمري أكثر من ثلاثين سنة، ومتزوجة منذ خمسة عشر عاماً، وعندي أولاد والحمد لله، لكنني اضطررت للخروج من بلدي مع غيري من النساء والأمهات والزوجات والأخوات، وبقي زوجي بين أيدي الظالمين بعيداً، ودارت السنين وطالت مدة غيابه إلى ست سنوات، وانتقلت مع أطفالي من بلد إلى بلد، ومن قرية إلى قرية، وأنا الآن أستقر في هذا البلد الأمين منذ عامين، وخلال هذه المدة تعرفت على شاب في الرابعة والعشرين من عمره، وطلب مني الزواج، وتعهد بأن يرعى الأولاد رعاية تامة، وهو يقف في طريقي كلما رآني ذاهبة إلى الحرم النبوي، ويسألني عن رأيي في هذا الزواج، فيا ترى هل يحق لي أن أطلب الزواج منه وأتطلق من زوجي القديم الذي لا أعرف أخباره منذ أن خرجت من بلدي، وهل يسمح لي النظام بذلك، وهل يترك لي فرصة أن أحضر أولادي معي إلى بيت الزوج الجديد، وهل يحق لأهل زوجي أو لأهلي أن يعارضوني في هذا الأمر، أفيدوني أفادكم الله مع العلم أنني أخشى على نفسي إن لم يتم الزواج بهذا الرجل أن يوقع الشيطان بيننا ما لا يرضاه الله سبحانه؟","title":"غاب زوجها ست سنوات وتريد الزواج من آخر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذه المسألة يجب أن تسأل عنها المحكمة في المدينة المنورة، ولا ريب أن جلوسك بدون زوج فيه خطر، ونسأل الله لنا ولك العافية، ولكن عليك أن تتصلي بالمحكمة وأن تشرحي للمحكمة ما ذكرت في السؤال، والمحكمة تقوم بالواجب إن شاء الله في أمر زواجك، وفيما يتعلق بزوجك الغائب، هذا هو الذي يجب عليك، ونسأل الله لك التوفيق وحسن العاقبة.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7455/غاب-زوجها-ست-سنوات-وتريد-الزواج-من-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23601.mp3","categories":["غياب وفقدان الزوج"]},{"id":9536,"question":"وهذه رسالة من المرسل (ب. ج. ع) لم يذكر عنواناً يقول في رسالته: سمعت من بعض الأشخاص الذين أظن أن عندهم دراية بالدين، أن المسلم إذا سافر إلى أي دولة وغاب عن زوجته مدة سنة وهي تعلم مكانه ويراسلها وترسل له ويرسل لها النفقة، فإذا ذهب إلى بيته بعد سنة لا يصح له أن يجتمع بها قبل أن يعطيها فلوس يسمونها: محللة، وهي حرة في هذه الفلوس تتصرف بها كيف تشاء وبعد أن يعطيها الفلوس يتم النكاح ويجوز له أن يقربها أفيدونا عن صحة ذلك بارك الله فيكم؟","title":"هل يجب على الزوج دفع نقوداً لزوجته تعويضا عن غيبته؟","answer":"الجواب: هذا شيء لا أصل له، هذه الفلوس لا أصل لها، إذا غاب عنها ولم يطلقها فهي زوجته ولو غاب أكثر من سنة هي زوجته إلا أن يطلقها أو تفسخ منه، فما دامت في حباله وفي عصمته لم تفسخ من جهة القاضي الشرعي ولم يطلقها هو فإنها زوجته، وإذا قدم من سفره فهي زوجته له الاتصال بها وجماعها، وإن لم يعطها نقوداً يكفيها النفقة التي فرض الله لها، فالحاصل أن هذا الشيء الذي ذكره السائل كونها لا تحل له بعد قدومه حتى يعطيها فلوس هذا لا أصل له، بل هي زوجته تحل له مادام لم يطلقها ولم تفسخ منه، لم يفسخها القاضي الشرعي لأسباب تخلفه عنها، أو لأسباب عدم نفقته عليها أو نحو ذلك فهي زوجته. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7697/هل-يجب-على-الزوج-دفع-نقودا-لزوجته-تعويضا-عن-غيبته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_245/24509.mp3","categories":["غياب وفقدان الزوج"]},{"id":9584,"question":"يسأل ثانية في نفس رسالته الأخ فارس نصر الليثي حول قضية الحقيقة تتكرر لدينا في كثير من الأسئلة بشكل عجيب، وهي قضية جواز السفر وترك الزوجة لأكثر من سنة أو ستة أشهر، وأن هذا فيه شيء من التقصير تجاه الزوجة وأنه يلزمه الرجوع وما إلى ذلك، مع أن بعض الناس مضطر للسفر والغربة من أجل البحث عن الرزق، فيسأل عن ذلك؟","title":"ضابط السفر عن الزوجة ومدة الغياب عنها","answer":"الجواب: لا حرج على الزوج أن يسافر لطلب العلم أو لطلب الرزق ولا حد لسفره، لا بستة أشهر ولا بغير ذلك، ولكنه مهما استطاع أن يسافر بها معه إذا كانت الحال تؤمن، فينبغي له أن يسافر بها إذا استطاع ذلك، أما إذا لم يستطع فإنه يبقيها في محل آمن ويسافر لطلب العلم أو طلب الرزق، ويحرص على أن يعجل العود إليها بين وقت وآخر مراعاة لظروفها وظروفه جميعاً ولا يتحدد بالوقت، ولو كان أمير المؤمنين عمر بن الخطاب  حدد للجند ستة أشهر اجتهاداً منه حيث تيسر ذلك، فإذا تيسر له أن يأتي بعد ستة أشهر أو بعد أربعة أو خمسة أو ثلاثة هذا طيب حسن، وبكل حال فينبغي له أن يلاحظ ما يجمع بين المصالح، وحال المرأة تختلف؛ قد تكون في محل آمن فلا يخشى عليها ولو طال السفر، وقد تكون في محل غير آمن ويخشى عليها فينبغي له أن يعجل الرجوع إليها، ويحرص على تأمين حالها أو نقلها معه، فهذا الأمر يختلف باختلاف أحوال الزوج وأحوال الزوجة وأحوال البلاد والأمن عن المرأة وعدم الأمن، فحيث كان الأمن متوفراً فالأمر أوسع، وحيث كان الأمر غير متوفر فالواجب عليه أن يراعي ذلك بتعجيل الأوبة وعدم إطالة السفر أو بنقلها معه، حتى يطمئن إلى ذلك ويسلم من الخطر وتسلم هي أيضاً من خطر الغربة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7752/ضابط-السفر-عن-الزوجة-ومدة-الغياب-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_248/24807.mp3","categories":["غياب وفقدان الزوج"]},{"id":9590,"question":"يسأل ثانية في نفس رسالته الأخ فارس نصر الليثي حول قضية الحقيقة تتكرر لدينا في كثير من الأسئلة بشكل عجيب، وهي قضية جواز السفر وترك الزوجة لأكثر من سنة أو ستة أشهر، وأن هذا فيه شيء من التقصير تجاه الزوجة وأنه يلزمه الرجوع وما إلى ذلك، مع أن بعض الناس مضطر للسفر والغربة من أجل البحث عن الرزق، فيسأل عن ذلك؟","title":"ضابط السفر عن الزوجة ومدة الغياب عنها","answer":"الجواب: لا حرج على الزوج أن يسافر لطلب العلم أو لطلب الرزق ولا حد لسفره، لا بستة أشهر ولا بغير ذلك، ولكنه مهما استطاع أن يسافر بها معه إذا كانت الحال تؤمن، فينبغي له أن يسافر بها إذا استطاع ذلك، أما إذا لم يستطع فإنه يبقيها في محل آمن ويسافر لطلب العلم أو طلب الرزق، ويحرص على أن يعجل العود إليها بين وقت وآخر مراعاة لظروفها وظروفه جميعاً ولا يتحدد بالوقت، ولو كان أمير المؤمنين عمر بن الخطاب  حدد للجند ستة أشهر اجتهاداً منه حيث تيسر ذلك، فإذا تيسر له أن يأتي بعد ستة أشهر أو بعد أربعة أو خمسة أو ثلاثة هذا طيب حسن، وبكل حال فينبغي له أن يلاحظ ما يجمع بين المصالح، وحال المرأة تختلف؛ قد تكون في محل آمن فلا يخشى عليها ولو طال السفر، وقد تكون في محل غير آمن ويخشى عليها فينبغي له أن يعجل الرجوع إليها، ويحرص على تأمين حالها أو نقلها معه، فهذا الأمر يختلف باختلاف أحوال الزوج وأحوال الزوجة وأحوال البلاد والأمن عن المرأة وعدم الأمن، فحيث كان الأمن متوفراً فالأمر أوسع، وحيث كان الأمر غير متوفر فالواجب عليه أن يراعي ذلك بتعجيل الأوبة وعدم إطالة السفر أو بنقلها معه، حتى يطمئن إلى ذلك ويسلم من الخطر وتسلم هي أيضاً من خطر الغربة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7752/ضابط-السفر-عن-الزوجة-ومدة-الغياب-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_248/24807.mp3","categories":["غياب وفقدان الزوج"]},{"id":9639,"question":"السؤال الثاني في رسالة الأخ فضل محمد أحمد السوداني يقول فيه: ما هو الزمن المسموح به شرعًا في الاغتراب عن الزوجة أفيدونا أفادكم الله؟","title":"مدة اغتراب الرجل عن أهله","answer":"الجواب: ليس في هذا حد محدود عن النبي ﷺ، وإنما يروى عن عمر  أنه حدد بستة أشهر للجنود، وهذا من اجتهاده  لما شاور ابنته حفصة في ذلك، فإذا تيسر للمسافر أن يقتصر على هذه المدة -ستة أشهر- هذا حسن، وإن رجع إلى أهله في أقل من ذلك فهذا أولى وأحوط؛ لأن هذا العصر عصر الغربة والأخطار فيه كثيرة ليس مثل عصر الصحابة ، فعصرنا الآن فيه التبرج الكثير وتبذل النساء وكثرة الشباب المنحرف وجلساء السوء، فالذي ينبغي للمؤمن أن لا يطول السفر وأن يرجع إليها بين وقت وآخر قريب كشهرين أو ثلاثة أو أقل من ذلك إذا أمكنه ذلك فإن شق لطول السفر وبعد المسافة فلا حرج إن شاء الله ولو أكثر من ستة أشهر، إذا دعت الحاجة إلى ذلك كونه يدرس الطب ويدرس الهندسة في بلاد بعيدة أو يدرس العلم الشرعي أو نحو ذلك فعليه أن يتحرى ما أمكنه قصر الوقت؛ لأن هذا أقرب إلى السلامة، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/7805/مدة-اغتراب-الرجل-عن-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19402.mp3","categories":["غياب وفقدان الزوج"]},{"id":9641,"question":"السؤال الثاني في رسالة الأخ (ح. ع. س) من الأردن يقول فيه: هل صحيح ما نسمع من أن المرأة الغائب عنها زوجها مدة سنة أو أكثر يحق للقاضي التفريق بينهما حتى ولو أن مالًا وعقارًا تنفق منه على حوائجها الشرعية، ما حكم الإسلام في ذلك، أفيدونا أفادكم الله؟","title":"المرأة إذا غاب عنها زوجها سنة فأكثر هل للقاضي التفريق بينهما","answer":"الجواب: ليس هذا صحيحًا بل من غاب عنها زوجها وطالبت في الفراق فالقاضي ينظر في الأمر هل يكاتب زوجها لعله يحضر أو يعرض عذره ويعرف أسباب طلبها الفراق، ولا تجوز العجلة بقبول قولها مطلقًا لا ليس لهذا أصل، ولكن متى غاب عنها وطلبت الفراق ينظر في أمرها وفي أمره ويكون القاضي في ذلك على اهتمام وعلى عناية بالأسباب التي أوجبت طلبها الفراق وبالأسباب التي يوجب الفراق وهو يجتهد ويتحرى الحق وينظر ما قاله أهل العلم ويتوصل في الأدلة ويحكم بعد ذلك بما ...الله. نعم.","link":"https://binbaz.org.sa/fatwas/7807/المراة-اذا-غاب-عنها-زوجها-سنة-فاكثر-هل-للقاضي-التفريق-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19404.mp3","categories":["غياب وفقدان الزوج"]},{"id":10036,"question":"هل تحرم الزوجة على زوجها إذا غاب عنها ست سنوات في الخارج وليس له أولاد منها؟","title":"حكم غياب الزوج عن زوجته عدة سنوات","answer":"الجواب: لا تحرم عليه سواء غاب ست أو أكثر، لا تحرم عليه زوجته بغيبته إلا إذا طلقها أو فسخت منه إذا طلقها الطلاق الشرعي واعتدت، أو فسخها الحاكم الشرعي لطول الغيبة وعدم قيامه بحقها هذا تحرم عليه بالفسخ الشرعي أو بالطلاق الشرعي، أما مجرد الغيبة فالغيبة لا تحرمها عليه سواءً ست سنوات أو أقل أو أكثر. نعم.\nالمقدم: جزاكم الله خيراً، سماحة الشيخ هل لكم من كلمة حول هذه الغيبة الطويلة ست سنوات؟\nالشيخ: الواجب على الزوج أن يتقي الله في زوجته وأن يحرص على عدم طول الغيبة، حتى ولو كان في أمور مهمة يحرص على عدم طول الغيبة، سواءً كان في طلب العلم أو في تجارة أو في غير ذلك.\nالواجب عليه أن يحرص على حفظ زوجته ورعايتها حتى لا تقع فيما حرم الله وحتى لا يخل بما أوجب الله عليه يحرص على المجيء إليها بعد وقت قصير، كثلاثة أشهر شهرين أربعة خمسة ستة، يراعي الأمور التي تحول بينها وبين الشر وتحول بينه أيضاً وبين الشر؛ لأنه على خطر أيضاً حتى هو، إذا غاب على خطر من وقوع الفاحشة وهي على خطر أيضاً.\nفالواجب على كل منهما الحرص على أسباب العفة وعلى أداء الحق الذي عليه للآخر وطول الغيبة من أسباب إضاعة الحقوق، فالواجب على الزوج أن يحرص على عدم طول الغيبة وعلى الزوجة أن تحرص على مساعدته على هذا الشيء بالكلام الطيب والأسلوب الحسن والمطالبة بعدم طول الغيبة، أو سفرها معه إذا أمكن سفرها معه إلى محل ما فيه خطر تسافر معه حتى لا يخل بالواجب عليه وحتى يحصل الجمع والوئام بينهما على ما يحبه الله ويرضاه .\nأما السفر إلى بلاد الشرك فهذا خطر عظيم، فالواجب الحذر من ذلك لا سفره وحده ولا سفره معها كل ذلك فيه خطر عظيم، فيجب الحذر من الذهاب إلى بلاد الشرك لا في أوقات العطل ولا في غيرها، لأن بلاد الشرك خطرها عظيم من جهة الشرك ومن جهة المعاصي ومن جهة مرض القلوب إلى غير هذا من الأخطار، أما في بلاده الإسلامية ومنها المحلات التي ليس فيها خطر لعمل ذهب إليه، أو لتجارة أو لأمور رسمية، فالواجب عليه أن يحرص على أن تكون المدة قصيرة أو أن تكون معه في سفرته حرصاً على المصلحة العظيمة التي يحتاجها وتحتاجها هي، وحرصاً أيضاً على السلامة من كل شر نسأل الله للجميع الهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8210/حكم-غياب-الزوج-عن-زوجته-عدة-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30112.mp3","categories":["غياب وفقدان الزوج"]},{"id":10288,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العراقية، وباعثها أحد الإخوة المصريين من هناك يقول: أخوكم وهبة الشربيني السيد يسأل ويقول: ما حكم الإسلام فيمن غاب عن زوجته ثلاث سنوات، أي: سافر إلى الخارج، ويقول: إن زوجته راضية عن هذا السفر، فما هو الزمن المحدد الذي حدده الإسلام بين الزوج وزوجته، وهل تراضي الزوجين يغير من الزمن المحدود؟","title":"غياب الزوج عن زوجته مدة طويلة برضاها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإذا سافر الرجل عن زوجته مدة طويلة أو قصيرة برضاها فلا حرج في ذلك ولو طالت المدة.\nولكن ينبغي للمؤمن أن يلاحظ حاجة أهله إلى مجيئه إليهم، وأن يحرص على أسباب السلامة من الفتنة؛ لأن المرأة إذا تأخر عنها الزوج قد يخشى عليها من الفتنة، فينبغي للزوج أن يلاحظ ذلك وأن لا يطيل الغيبة، وإذا اتفق معها على شيء معلوم فلا بأس بذلك؛ لأن الحق لا يعدوهما، ولكنه مع ذلك ينبغي له أن يتحرى الوقت القصير الذي يحصل به المقصود من قضاء حاجته مع كونه يتصل بها ولا يبتعد عنها مدة طويلة.\nوقد روي عن عمر  أنه وقت للجنود ستة أشهر، وهذا مقارب ولكن الوقت يختلف والناس يختلفون ولاسيما في هذا العصر، الذي كثر فيه الشر وعظمت فيه أسباب الفتن، فينبغي للزوج أن يتحرى الوقت القصير أو يحملها معه إلى محل عمله، حذرًا من الفتنة والعواقب الوخيمة، وليس في ذلك حد محدود بل على العبد أن يتحرى الوقت المناسب الذي يرجو معه سلامة نفسه وسلامة زوجته، فهو قد يفتن بسبب طول الغيبة، قد يقع فيما حرم الله، وهي كذلك يخشى عليها من الفتنة أيضًا.\nفعليه أن يراعي ذلك من جهة نفسه ومن جهة زوجته، في تقصير المدة أو بنقلها معه إلى محل عمله، والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيرًا، إذا اتفقا على مدة معينة كما ينص أخونا صاحب السؤال؟\nالشيخ: مثلما تقدم إذا اتفقا فلا حرج، الحق لا يعدوهما. نعم.\nالمقدم: لكن تنصحون الزوج .......\nالشيخ: لكن مع اتفاقهما ينبغي أن تكون المدة قصيرة؛ لأنها قد ترضى وليست راضية، قد ترضى ولكن مراعاة لخاطره، وهي لا ترضى بذلك في الحقيقة وهو عليه خطر أيضًا من طول المدة؛ لأنه قد يفتن في دينه قد يفتن بغيرها، والإنسان مجبول على الميل إلى النساء وهي مجبولة على الميل إلى الرجال، والشهوة تختلف فليس كل واحد يملك إربه.\nفينبغي له أن يحرص على تقصير المدة، وهي كذلك ينبغي لها أن تحرص على أسباب السلامة وأن تحرص منه على أن تكون المدة قصيرة من دون تسبب فيما يسبب الطلاق بينهما. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8445/غياب-الزوج-عن-زوجته-مدة-طويلة-برضاها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_338/33801.mp3","categories":["غياب وفقدان الزوج"]},{"id":10425,"question":"من المستمع محمود محمد حسن هكبة ، صومالي بعث يقول: أنا صومالي وأعمل في المملكة، وغبت عن زوجتي ما يقرب من ثلاث سنوات، فماذا يكون علي؟ وبم تنصحونني في المستقبل جزاكم الله خيراً؟","title":"غياب الزوج عن زوجته للعمل مدة ثلاث سنوات","answer":"الجواب: هذه مدة طويلة لا ينبغي لك فعلها، لكن إذا كانت قد سمحت عنك ورضيت فلا بأس، وإلا فالذي ينبغي لك أن لا تطول المدة، يروى عن عمر رضي الله عنه ابن الخطاب أمير المؤمنين أنه وقت للجنود ستة أشهر، وفي الوقت الحاضر قد تكون الستة طويلة أيضاً؛ لكثرة الشرور، وقلة الاحتراز من النساء، فينبغي للرجل أن لا يطول، إما أن ينقلها معه في محل العمل وإما أن يرجع إليها بين ثلاثة أشهر.. أربعة أشهر حتى يقضي حاجته ويقضي حاجتها، ويعرف أحوالهم ويقضي حاجاتهم، فإذا كان ولابد ستة أشهر وهي طويلة أيضاً، فالمقصود أنه يجتهد المؤمن في عدم التطويل مهما استطاع، أو ينقلها معه حرصاً على سلامتها وسلامته هو على خطر وهي على خطر، فكل منهما يحرص على السلامة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8596/غياب-الزوج-عن-زوجته-للعمل-مدة-ثلاث-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_317/31704.mp3","categories":["غياب وفقدان الزوج"]},{"id":10621,"question":"أنا متزوج وسافرت إلى العراق ولم أذهب إلى أهلي منذ ثلاث سنوات، هل علي من ذنب يلحقني نتيجة ما فعلت، وجهوني جزاكم الله خيراً؟","title":"حكم الغياب عن زوجته ثلاث سنوات","answer":"الجواب: هذه مدة طويلة ما كان ينبغي منك أن تفعلها؛ لأن المرأة بحاجة إلى زوجها؛ لعفتها والبعد بها عن الأخطار، وأنت كذلك في حاجة إلى زوجتك للعفة وغض البصر، فالواجب أن لا تطيل المدة، وأن تحرص على أن تكون المدة قليلة أو تنقلها معك إلى محل عملك، وإذا كانت قد سمحت عنك فلا شيء عليك إن شاء الله، لكن ينبغي لك أن تلاحظ الموضوع دائماً وأن تكون المدة قصيرة، حرصاً على سلامتك وسلامتها، وحرصاً على عفة فرجك وغض بصرك، وهكذا سلامتها هي أيضاً والحرص على حفظ فرجها وغض بصرها، والمؤمن حسيب نفسه ينظر الأمر، فإن المدة إذا طالت فهي خطر عليكما جميعاً.\nفالواجب عليك أن تجتهد في اختصار المدة قليلاً.. في اختصار المدة حتى تكون قليلاً ليس فيها خطر، أو أن تنقل المرأة معك في محل عملك، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيراً، سماحة الشيخ! علمت منكم قولاً تحددونه للرجل عندما يريد أن يغيب عن زوجته، كم المدة التي ترونها. جزاكم الله خيراً؟ الشيخ: يروى عن عمر أنه كان يحدد ستة أشهر ، ولكن الوقت يختلف؛ فالستة الأشهر مقاربة كما قال عمر ، ولكن في أوقاتنا هذه الخطر كبير، بسبب انتشار الفساد، وكثرة التبرج، وضعف الإيمان في أغلب البلدان وأغلب الأمكنة، فينبغي للمؤمن أن يختصر المدة، وأن تكون أقل من ذلك مهما أمكن، أو يصحب زوجته معه دائماً؛ لأن ذلك أقرب إلى سلامته وسلامتها.\nالمقصود مهما أمكن أن تكون المدة أقل من ستة أشهر، فهو أولى من أجل الأخطار الكثيرة على الرجل والمرأة جميعاً. نعم.\nالمقدم: جزاكم الله خيراً، هل من كلمة للنساء حول هذا الموضوع شيخ عبد العزيز ؟\nالشيخ: نعم، الوصية تقوى الله جل وعلا، وأن تحرص على حفظ فرجها وسمعتها وغض بصرها، وأن تبتعد عن الخلطة بالرجال، أو الخلوة بالرجال، وأن تحرص على بقائها في بيتها، وإن كان ولا بد من الخروج فلتكن إلى محلات أمينة سليمة، وليكن معها من أخواتها في الله من يصحبها؛ لأن ذلك أبعد عن أسباب الفتنة، عند الضرورة إلى الخروج لقضاء حاجة.\nوعلى الزوج أن يتقي الله في أهله وأن يحرص على قلة المدة التي يغيب عنها، أو يحرص على صحبتها معه أينما كان حرصاً على سلامتهما جميعاً. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8792/حكم-الغياب-عن-زوجته-ثلاث-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_327/32704.mp3","categories":["غياب وفقدان الزوج"]},{"id":11045,"question":"السائل من جمهورية مصر العربية -المنصورة- مقيم في القصيم -بريدة- أبو أحمد يقول: فضيلة الشيخ! أسأل قبل سفري إلى المملكة اتفقت مع زوجتي على أن أقضي مدة سنة واحدة خارج البلاد، وذلك لسداد الديون المطالب بها، فإذا طالت مدة سفري عن السنة المتفق عليها وذلك لظروفي المادية هل يكون علي وزر من ناحيتها؟ أفيدوني مأجورين.","title":"حكم غياب الرجل عن زوجته مدة طويلة","answer":"الجواب: ليس عليك شيء -إن شاء الله- إذا كنت مضطرًا لزيادة الإقامة لا حرج في ذلك، لكن إذا تيسر أن تجلبها إلى محلك، أن تدعوها إلى محلك، وتنقلها إلى محلك يكون هذا أحوط وأحسن، فإن لم يتيسر ذلك فلا حرج، نعم.","link":"https://binbaz.org.sa/fatwas/9223/حكم-غياب-الرجل-عن-زوجته-مدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28801.mp3","categories":["غياب وفقدان الزوج"]},{"id":11449,"question":"يسأل ويقول: ما هو الشيء الذي يترتب على الرجل الذي سافر؛ طلبًا للعمل، وترك زوجته لمدة سنة؟ أفيدونا أفادكم الله.","title":"حكم غياب الرجل عن زوجته مدة طويلة طلباً للرزق","answer":"الجواب: ننصحه بأن يقصر المدة، تكون المدة قليلة؛ حتى لا تقع عائلته في خطر، أو تسافر معه إذا أمكن، تكون معه في السفر إذا أمكن؛ لأن الوقت خطير، والفتن كثيرة، فالواجب على الزوج أن يحذر، ما يضر زوجته، أو يعرضها للشر والفساد، ولا شك أن المدة الطويلة قد تفضي إلى خطر على الزوجة، ثم أيضًا هي محتاجة إلى زوجها كما أنه محتاج إليها، فقد يقع في الخطر هو لطول المدة، وقد تقع هي في الخطر.  فالنصيحة ألا يطول، بل يتردد بين عمله، وبين زوجته، شهر، ثلاثة أشهر، شهرين، أربعة أشهر، وكان عمر  قد وقت للمجاهدين ستة أشهر للمرابطين، ولكن في الوقت الحاضر الوقت أخطر، والستة طويلة؛ فينبغي للعاقل أن يحذر أسباب الفتنة على نفسه، وعلى زوجته، وأن تكون المدة قصيرة؛ حذرًا من أسباب الفتنة، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9630/حكم-غياب-الرجل-عن-زوجته-مدة-طويلة-طلبا-للرزق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38105.mp3","categories":["غياب وفقدان الزوج"]},{"id":11458,"question":"أيضًا يسأل عن الغياب، عن الزوجة -سماحة الشيخ- فيقول: سمعت من بعض الناس أن الذي يغيب عن زوجته لمدة سنة تكون زوجته طالقًا، وأن هذا غير جائز، فما هو توجيه سماحتكم؟ جزاكم الله خيرًا.","title":"هل غياب الرجل عن زوجته مدة سنة يجعلها مطلقة؟","answer":"الجواب: لا، لا تطلق بغيبته، لا تطلق زوجته بغيبته، ولكن يشرع له أن يراعي الأوقات المناسبة، وألا تطول الغيبة؛ لأن طول الغيبة قد يسبب مشاكل كثيرة عليه وعليها، والإنسان عرضة للفتنة الرجل والمرأة، فالمشروع لك -يا أخي- ألا تطول الغيبة، وأن تحرص على أن تكون الغيبة قليلة، شهرين ثلاثة، أو تكون معك إذا أمكن؛ حرصًا على سلامة عرضها وعرضك. أما الطلاق فلا تكون مطلقة، لو تأخرت عنها سنة، أو أقل، أو أكثر، ولم تطلقها؛ فهي باقية في عصمتك، إلا إذا كان هناك خصومة بينك وبينها عند الحاكم في المحكمة، ورأت المحكمة الفراق بينك وبينها، هذا شيء إلى المحكمة، هذا شيء يرجع إلى المحكمة، تنظر في الأمر الموضوع، وتعمل بما يقتضيه الشرع المطهر، أما مجرد غيبتك عنها؛ فلا يجعلها مطلقة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9639/هل-غياب-الرجل-عن-زوجته-مدة-سنة-يجعلها-مطلقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38113.mp3","categories":["غياب وفقدان الزوج"]},{"id":11544,"question":"مستمع من جمهورية مصر العربية هو عبدالسلام عطية يقول: سمعت أن من غاب عن زوجته ستة أشهر، أو أكثر؛ يجب عليه عند وصوله إليها أن يعقد عليها عقدًا شرعيًا جديدًا، وأنا غبت عنها ثلاث سنوات متتالية، فهل ما قاله الناس صحيح؟","title":"حكم غياب الزوج عن زوجته مدة طويلة","answer":"الجواب:  هذا ليس بصحيح، لو غاب عنها سنوات هو على نكاحه، إلا إذا فسخه الحاكم الشرعي، إذا اشتكت إلى الحاكم الشرعي، وفسخه الحاكم الشرعي؛ فهذا يراجع فيه الحاكم، إذا أراد العودة إليها بعقد جديد؛ يراجع الحاكم، أما إذا كانت على حالها لم تطلب الطلاق، ولم تفسخ؛ فنكاحه باقي، وزوجته باقية في حباله وعصمته، وليس هناك حاجة للعقد، سواء كانت مدة قصيرة أو طويلة. لكن ينبغي للمؤمن أن يجتهد في عدم الإطالة؛ لأن المرأة خطر، وهو عليه خطر أيضًا، كذلك لطول الغيبة، فينبغي له أن يكون عنده عناية بزوجته، وألا يطول الغيبة عنها، والله يقول سبحانه: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، وليس من المعروف طول الغيبة، بل ينبغي له أن يأتي إليها بين وقت وآخر حتى تنتهي مدته، كل ثلاثة أشهر كل شهرين كل أربعة أشهر، حتى لا تطول الغيبة.  وقد روي عن عمر  أنه سئل عن هذا من جهة الغزاة؛ فوقت لهم ستة أشهر، فإذا غاب ستة أشهر لحاجة مهمة؛ فلا بأس إن شاء الله، ولكن كل ما أمكن من التقصير، وعدم التطويل؛ فهو أولى وأحوط، ولا سيما في هذا العصر الذي كثرت فيه الفتن، وكثرت فيه الشرور، وقل فيه الصبر.  فينبغي للمؤمن أن يعرف قدر وقته، وألا يطيل الغربة عن زوجته، بل يزورها بين وقت وآخر من سفره، أو يحملها معه حيث أمكن حملها معه في السفر، وإلا فليأت بين وقت وآخر أقل من ستة أشهر، في شهرين.. ثلاثة.. أربعة، كلما تيسر له جاء، وزار أيامًا، ثم رجع حتى ينتهي عمله، نسأل الله للجميع التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/9727/حكم-غياب-الزوج-عن-زوجته-مدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_295/29511.mp3","categories":["غياب وفقدان الزوج"]},{"id":12553,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين هو (ص. ح) أخونا بعث برسالة يقول فيها: رجل اختفى لسبب، أو لآخر مدة ثمان سنوات؛ حتى أصبح لا يعرف عنه شيئًا، فطلبت زوجته الطلاق، فحصلت عليه، ثم تزوجت، وبعد ذلك ظهر الزوج المختفي فجأة، واتضح من خلال قوله أنه كان سجينًا، فهل يمكنه المطالبة بإعادتها إلى عصمته، وهل لها رأي في اختيار أحد الزوجين؟ نرجو الإيضاح جزاكم الله خيرًا.","title":"حكم الرجل إذا فُقِدَ ثم رجع وقد تزوجت امرأته","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذه المسألة وأشباهها إنما تحل من طريق المحكمة، يرجع إلى المحكمة إذا كان له رغبة فيها، والمحكمة تنظر في الأمر. نعم. المقدم: لثقافة المستمع ووعيه بمثل هذه الأمور ماذا تقولون؟ الشيخ: أقول في مثل هذا إذا وقعت صاحب الحاجة يتصل بالحاكم الشرعي، ويسأله ويخبره بالواقع، وصاحب الحكم ينظر في الأمر، قد قرر العلماء هذه المسألة، وبينوا حال الرجل، هل له الرجوع إليها، أم لا، وفرقوا بين ما إذا كان قبل الدخول، أو بعد الدخول. فالحاصل: أن له نظر، لابد من ثبوت الواقع، وتفاصيل الواقع. نعم. المقدم: إذًا القضية في هذه الرسالة غير واضحة؟ الشيخ: نعم، حلها لا يمكن إلا من طريق المحاكم.. يرى في الواقع على بصيرة، نعم. المقدم: بارك الله فيكم، أما إذا كان الواقع واضحًا؛ كانت الإجابة ممكنة. الشيخ: نعم متيسرة، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10754/حكم-الرجل-اذا-فقد-ثم-رجع-وقد-تزوجت-امراته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_410/41001.mp3","categories":["غياب وفقدان الزوج"]},{"id":12700,"question":"المستمع حسين سليم جلال بعث برسالة ضمنها جمعًا من الأسئلة، أسئلته كتبها بلهجتها العامية إنما لخصتها في التالي: أولًا: غاب عن زوجته ما يقرب من عامين ونصف، ويسأل هل هو آثم والحال ما ذكر؟","title":"الغياب عن الزوجة مدة عامين ونصف","answer":"الجواب: هذا فيه تفصيل، إذا كان له عذر شرعي؛ فليس بآثم، كالمسجون وأشباهه الذين لا يستطيعون الرجوع، أو سمحت له بذلك، أو في طلب الرزق؛ لأنه ليس في بلده عمل، ولم يتيسر له الخلاص من البلد التي ذهب إليها، إلا في هذه المدة الطويلة. المقصود: إذا كان له عذر شرعي لم يمكنه من الرجوع في مدة قريبة. والأولى بالمؤمن أن يلاحظ المدة المناسبة مثل ستة أشهر، أو ما يقاربها حتى يرجع إلى أهله، أو يحمل أهله معه، ولا يطول الغيبة؛ لأن هذا فيه خطر على أهله، وخطر عليه أيضًا هو، وليس في هذا حد محدود إلا ما روي عن عمر  أنه كان يحدد ستة أشهر للغزاة والموظفين، هذا له وجه، فإذا اعتمد الإنسان ستة أشهر، فرجع إلى أهله، ثم عاد إلى عمله؛ فهذا -إن شاء الله- فيه خير كثير، وإن اعتنى بما هو أقل من هذا؛ لأن الوقت تغير، والخطر كبير، ورجع قبل ستة أشهر، كأربعة أو ثلاثة، فهذا فيه حيطة، وفيه عناية بنفسه، وعناية بأهله، أو يحملهم معه، ولو سمحنا، ولو سمحت الزوجة له، قد تسمح وغير مطمئنة، وغير -يعني- راضية، لكن مراعاة، قد تصبر مراعاة لخاطرة، فينبغي له أن يحتاط، ينبغي للمؤمن أن يحتاط من جهة أهله، فلا يطول الغيبة مهما أمكن. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10910/الغياب-عن-الزوجة-مدة-عامين-ونصف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45905.mp3","categories":["غياب وفقدان الزوج"]},{"id":12866,"question":"المستمع: أحمد محمد جفول سوداني مقيم في المملكة يسأل ويقول: إذا غاب الرجل عن زوجته طلبًا للقمة العيش، فمكث عشرين شهرًا، هل يكون آثمًا؟","title":"إذا غاب الرجل عن زوجته طلبًا للقمة العيش هل يكون آثمًا","answer":"الجواب: نرجو ألا حرج عليه إذا اضطر إلى ذلك؛ لأنه مأمور بطلب الرزق، فإذا لم يتيسر له في بلاده ذلك، واضطر إلى السفر؛ فلا حرج عليه، أما إذا استطاع أن يأتي إليها بين وقت وآخر، كستة أشهر، أو أقل من ذلك؛ فإنه يفعل ذلك، إلا إذا سمحت ورضيت، قالت: إنه لا يشق عليها؛ فلا بأس بذلك، ولكن الأولى به حتى ولو سمحت، الأولى به أن يعتني بالرجوع إليها في مدة قصيرة، كأربعة أشهر، خمسة أشهر، ستة أشهر، ويروى عن عمر  أنه وقت للجنود ستة أشهر. فالحاصل: أن غيبته الطويلة قد تضر بها، وتضر به، فالأولى بالمؤمن أن يحرص على عدم الغيبة الطويلة مهما استطاع، أما إذا اضطر إليها في طلب الرزق، أو طلب العلم، فلا حرج عليه -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11081/اذا-غاب-الرجل-عن-زوجته-طلبا للقمة-العيش-هل-يكون-اثما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_465/46516.mp3","categories":["غياب وفقدان الزوج"]},{"id":13335,"question":"آخر سؤال له يقول: غبت عن زوجتي ثمانية أشهر، فما الحكم؟","title":"حكم الغياب عن الزوجة لمدة ثمانية أشهر","answer":"الجواب: لا حرج في ذلك -إن شاء الله- عليك أن تجتهد في العود إليها، أو حملها معك إذا أمكن، إذا كان سفرك إلى بلاد سليمة، ليس فيها خطر، وإذا أمكنك أن تجتهد في سرعة الرجوع؛ فلا تتأخر، وإذا كانت سامحة؛ فلا بأس أيضًا. المقصود: أن سفرك في طلب الرزق، أو طلب العلم ثمانية أشهر، أو أقل، أو أكثر، حسب الحاجة، لا حرج فيه، لكن كلما قل؛ فهو أولى، وأحوط؛ حرصًا على سلامة دينك ودينها، وعفتك وعفتها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11621/حكم-الغياب-عن-الزوجة-لمدة-ثمانية-اشهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_476/47610.mp3","categories":["غياب وفقدان الزوج"]},{"id":13496,"question":"بعد ذلك ننتقل إلى رسالة السودان، السائل: (أ. أ) يقول: سماحة الشيخ! كثيرًا من الناس تدعوهم الظروف المعيشية طلبًا للهجرة، تاركين الزوجات، ومكتفين بإرسال المصروف دون مراعاة العودة، وضاربين بحقوق الزوجة عرض الحائط،  ما الحكم الشرعي، وما هي المدة القصوى لغياب الزوج عن زوجته في الحد الأدنى؟ جزاكم الله خيرًا.","title":"حكم الغياب عن زوجته مدة طويلة طلبًا للرزق","answer":"الجواب: ليس لهذا حد محدود كما نعلم شرعًا، ولكن يجب عليه أن يراعي حقها، فإذا سافر لطلب الرزق، وكسب الرزق، ثم يرسل لها حاجاتها، ونفقاتها؛ فلا بأس، وإذا كان يخشى عليها من بقائها وحدها؛ يجب عليه أن ينقلها معه، أو يبقى في البلد، ويطلب الرزق في البلد التي هي فيه، أو يطلقها، أما أن يهملها، ويضيعها؛ فلا يجوز، منكر ولا يجوز، بل يجب أن ينفق عليها، أو يوكل من ينفق عليها، ويذهب لطلب الرزق إذا كان بلده ما فيه عمل، يذهب يطلب الرزق في بلد آخر، ويرسل إليها حاجاتها، ونفقاتها، أو ينقلها معه، كل هذا واجب عليه، إلا إذا طابت نفسه منها ولا يريدها؛ فإنه يطلقها طلقة واحدة، والرزق عند الله، يقول الله : وَإِنْ يَتَفَرَّقَا يُغْنِ اللَّهُ كُلًّا مِنْ سَعَتِهِ [النساء:130]. وإذا كان السفر في سبيل الله، وفي سبيل الجهاد، فهو مأمور بالطاعة لولاة الأمور، وكان عمر  إذا أرسلهم يحد له ستة أشهر، ثم يقدمون إلى أهليهم، وهذا من اجتهاده  فإذا جعل ولي الأمر لهم ستة أشهر، أو أربعة أشهر إذا كان السفر بأمر ولي الأمر؛ فلا بأس يصبرون، يذهب ستة أشهر .. أربعة أشهر، على حسب ما يحدد ولي الأمر، وأكثرها ستة أشهر، كما فعله عمر، ثم يرجع إلى أهله. أما إذا أمكن أن تسافر معه زوجته في البلد، في بلد العمل الذي أرسل إليها كالسفير ونحوه؛ فإنه يسافر بها؛ حماية لها من الشر، وقضاء لوطره ووطرها، وحماية لأنفسهما جميعًا من الشر، فهو في حاجة إليها، وهي في الحاجة إليه. لكن إذا كان هناك موانع من السفر بها، فإنه يرسل نفقاتها، ويجتهد في العود إليها سريعًا، وإذا طلبت الفراق؛ فهذا يرجع إلى المحكمة الشرعية، إذا قصر في حقها، وظلمها؛ يرجع إلى المحكمة الشرعية في النظر في هذا الأمر، لكن عليه أن يتقي الله، وأن لا يحوجها إلى المحكمة، عليه أن يتقي الله، وأن يصطلح معها على وجه لا يضرها، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11804/حكم-الغياب-عن-زوجته-مدة-طويلة-طلبا-للرزق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_518/51810.mp3","categories":["غياب وفقدان الزوج"]},{"id":13600,"question":"السائل عادل خفاجي استعرضنا سؤالًا له في حلقة سابقة بقي له هذا السؤال يقول: من سافر مدة خمسة عشر شهرًا عن زوجته لطلب الرزق ماذا عليه؟","title":"حكم السفر والانقطاع عن الزوجة مدة طويلة","answer":"الجواب: إذا كان مضطرًا لذلك لا حرج عليه، إذا كان مضطرًا لذلك لا حرج عليه فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] أما إذا تيسر أنه يأتي إليها بعد شهرين ثلاثة أربعة ستة حسب التيسير فهذا أحوط وأولى لمصلحته ومصلحتها، لعفة فرجه، وعفة فرجها، يأتي إليها، ثم يعود، ثم يأتي، ثم يعود، هذا هو الأحوط إذا تيسر، أو ينقلها معه إذا تيسر، أما إذا اضطر إلى ذلك لشدة حاجته إلى المعيشة، وعدم تيسر نقلها معه، أو رجوعه إليها قبل المدة المذكورة؛ فلا حرج الحمد لله. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11934/حكم-السفر-والانقطاع-عن-الزوجة-مدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52720.mp3","categories":["غياب وفقدان الزوج"]},{"id":14545,"question":"في سؤال السائل (أ. ل. ع) يقول: يغيب البعض من العمال عن زوجاتهم سنين عديدة من أجل البحث عن لقمة العيش، ما رأي الشرع في نظركم سماحة الشيخ في غياب الرجل عن زوجته هذه السنين؟ وهل هو يأثم؟","title":"حكم الاغتراب عن الأهل لمدة طويلة","answer":"الجواب: إذا اضطر إلى ذلك لا حرج عليه، إذا اضطر إلى ذلك لطلب الرزق فلا حرج عليه في ذلك، وإن تيسر نقلها معه، نقلها معه، وإن تيسر أن يرجع إليها بعد ستة أشهر، ثم يرجع هذا حسن، كما جاء عن عمر  أنه وقت للمسافرين عن أزواجهم ستة أشهر الجنود، فإذا تيسر هذا فهو أحوط وأحسن وإلا فلا؛ لأن الإنسان قد يضطر إلى العمل، ولا يتيسر له الرجوع كل ستة أشهر، أو أقل أو أكثر، فإذا كان في طلب الرزق، وطلب الحلال وليس عنده في بلده ما يحصل به المقصود فإنه معذور، سواء طالت المدة أو قصرت على حسب القدرة، وإذا تيسر له أن ينقل زوجته معه فذلك أكمل وأحوط، وإذا رضيت في بقائها تنتظره، ولم تشدد في الموضوع فلا بأس، الحق لها إذا سمحت فلا بأس، وإن طالبت فإنه ينقلها معه إذا تيسر له ذلك، أو يأتيها كل ستة أشهر، أو ما يقاربها إذا تيسر له ذلك؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وإذا كان يخشى عليها من غيبته عنها فليرجع إليها، ولو كل ثلاثة أشهر ليقضي وطره ووطرها؛ وليحافظ على سلامة دينها على حسب قدرته. المقصود: أنه يتقي الله ما استطاع في نقلها معه، أو الرجوع إليها بين وقت وآخر حرصًا على سلامة دينها وعفتها، وهو معذور في طلب الرزق والسفر لطلب الرزق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13042/حكم-الاغتراب-عن-الاهل-لمدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_555/55507.mp3","categories":["غياب وفقدان الزوج"]},{"id":14602,"question":"عن الزيارة في الواقع يسأل سماحة الشيخ، ويقول: أنا أقيم بالعراق منذ حوالي سنتين، ويمكن أن تمر السنة كاملة دون أن أسافر إلى أهلي بحكم ظروف العمل هل يلحقني إثم؟","title":"حكم غياب الرجل عن أهله فترة طويلة","answer":"الجواب: ينبغي لك أن تحرص على الزيارة، ولكن لا يلزمك، إذا كانت الزوجة عندك الحمد لله، أما الزوجة فلا بد أن تكون عندك تنقلها إليك، أو تزورها بين وقت وآخر، في ستة أشهر أو أقل؛ لأن الوقت خطير، والمجتمع الآن فيه شر كثير.  فالواجب عليك أن تتحرى ما يسبب حفظ زوجتك، وسلامة عرضها بأن تنقلها إليك، أو تسافر إليها بين وقت وآخر، ليس بطويل؛ لعفتها ومراعاة أحوالها وشؤونها، والإحسان إليها إلى غير ذلك.  أما الوالدان والأقارب فيكفي المكاتبة والكلام الطيب، أو الكلام بالهاتف، وإذا تيسرت الزيارة فهذا أكمل وأحسن، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13106/حكم-غياب-الرجل-عن-اهله-فترة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63604.mp3","categories":["غياب وفقدان الزوج"]},{"id":14654,"question":"في سؤال السائل (أ. ل. ع) يقول: يغيب البعض من العمال عن زوجاتهم سنين عديدة من أجل البحث عن لقمة العيش، ما رأي الشرع في نظركم سماحة الشيخ في غياب الرجل عن زوجته هذه السنين، وهل هو يأثم؟","title":"حكم غياب المسافر عن أهله مدة طويلة","answer":"الجواب: إذا اضطر إلى ذلك لا حرج عليه، إذا اضطر إلى ذلك لطلب الرزق فلا حرج عليه في ذلك، وإن تيسر نقلها معه نقلها معه، وإن تيسر أن يرجع إليها بعد ستة أشهر، ثم يرجع هذا حسن، كما جاء عن عمر  أنه وقت للمسافرين عن أزواجهم ستة أشهر؛ الجنود، فإذا تيسر هذا فهو أحوط وأحسن، وإلا فلا؛ لأن الإنسان قد يضطر إلى العمل، ولا يتيسر له الرجوع كل ستة أشهر، أو أقل أو أكثر، فإذا كان في طلب الرزق طلب الحلال، وليس عنده في بلده ما يحصل به، المقصود فإنه معذور، سواء طالت المدة، أو قصرت على حسب القدرة، وإذا تيسر له أن ينقل زوجته معه فذلك أكمل وأحوط، وإذا رضيت ببقائها تنتظره، ولم تشدد في الموضوع فلا بأس الحق لها، إذا سمحت فلا بأس، وإن طلبت فإنه ينقلها معه إذا تيسر له ذلك، أو يأتيها كل ستة أشهر، أو ما يقاربها إذا تيسر له ذلك؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وإذا كان يخشى عليها من غيبته عنها فليرجع إليها، ولو كل ثلاثة أشهر ليقضي وطره ووطرها؛ وليحافظ على سلامة دينها على حسب قدرته. المقصود: أنه يتقي الله ما استطاع في نقلها معه، أو الرجوع إليها بين وقت وآخر؛ حرصًا على سلامة دينها وعفتها، وهو معذور في طلب الرزق، والسفر لطلب الرزق، نعم.","link":"https://binbaz.org.sa/fatwas/13143/حكم-غياب-المسافر-عن-اهله-مدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55920.mp3","categories":["غياب وفقدان الزوج"]},{"id":14785,"question":"رسالة وصلت إلى البرنامج من المستمع يعقوب محمد عبدالله، مقيم في الطائف، يقول: ما حكم الفترة التي أقضيها بالمملكة وتتراوح إلى سنتين، والزوجة راضية، هل أكون آثمًا، أو لا؟","title":"هل يأثم الزوج إذا طالت غربته عن زوجته برضاها؟","answer":"الجواب: لست بآثم، ما دامت راضية فلست بآثم، ولكن إذا تيسر لك زيارتهم زيارة أهلك بين وقت وآخر فهو خير وأفضل وأحوط وأبرأ للذمة؛ لأنها قد ترضى حياء ومراعاة لخاطرك، فالأفضل أنك ترحمها، وتعطف عليها، ولا تطول الغيبة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13278/هل-ياثم-الزوج-اذا-طالت-غربته-عن-زوجته-برضاها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63808.mp3","categories":["غياب وفقدان الزوج"]},{"id":14874,"question":"يقول: من أجل العمل أغيب عن زوجتي فترة معينة، تصل إلى سنة وسنة ونصف، من أجل المعيشة، هل علي ذنب؟","title":"حكم الغياب عن الزوجة من أجل المعيشة","answer":"الجواب: لا حرج في ذلك، ليس عليك حرج في ذلك، ما دمت خرجت لطلب المعيشة، وطلب الرزق، وهي راضية، ليس عندها مخالفة، فلا حرج عليك.  أما إن كانت غير راضية، فاتفق معها على مدة معلومة، أو اتصل بالقاضي أنت والمرأة حتى يحكما بينكما، أما إذا كانت راضية، وليس عندها مخالفة فلا حرج عليك.  والأفضل لك أن لا تطول المدة، واجتهد أن تكون المدة قصيرة ستة أشهر، أربعة أشهر، ثلاثة أشهر، ثم ترجع إلى عملك، تذهب إليها أيامًا، ثم تعود إلى عملك، هذا هو الأفضل لك، والأحوط لك؛ لأن المرأة في حاجة إلى زوجها، وقد تكون لها حاجات أخرى تحب أن تهديها لك، وقد يخشى عليها من الشيطان.  فالواجب عليك أن ترعى هذه الأمور، وأن تجتهد حسب الطاقة، حتى لا تطول المدة، فإذا عجزت عن ذلك، وهي راضية فلا حرج عليك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13362/حكم-الغياب-عن-الزوجة-من-اجل-المعيشة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64505.mp3","categories":["غياب وفقدان الزوج"]},{"id":15252,"question":"هذا سؤال من الأخ المستمع حسين حسنين حسين، يقول: إذا خرج الرجل، وسافر إلى أي دولة، أو أي قطر عربي، أو خلافه، وانقطع عن زوجته مدة سنة أو سنتين أو أكثر عن ذلك، ورجع بعد ذلك، فما الحكم؟الشيخ: أعد.المقدم: يقول: إذا سافر الرجل وخرج من بلده إلى أي دولة، أو أي قطر عربي وانقطع عن زوجته مدة سنة أو سنتين أو أكثر عن ذلك، ثم رجع بعد ذلك، فما الحكم بالنسبة لزوجته؟","title":"حكم انقطاع الرجل عن أهله السنة والسنتين","answer":"الجواب: لا حرج في ذلك -إن شاء الله- إذا كان في طلب الرزق، أو في طلب العلم، لا حرج في ذلك، وإذا كان يخشى أن يكون قصر في حقها وتساهل، فإنه يستسمحها، ويرجو منها السماح، وعدم المؤاخذة بما حصل من الطول. وبكل حال فالأمر في هذا -إن شاء الله- واسع، ولا سيما إذا كان الطول عن غير اختياره في طلب الرزق، أو في طلب العلم، فإنه في هذا يكون -إن شاء الله- معفوًا عنه. وأما إن كان من غير عذر، بل تساهل، فينبغي له أن يستسمحها، ويقول: يا بنت فلان، أو يا أم فلان، سامحيني قد قصرت، وطولت السفر من دون عذر له أهمية، والمشروع لها أن تسامحه أيضًا هي، وأن تعفو عما سلف، حتى تعود المياه إلى مجاريها، وحتى تستقيم حال العشرة فيما بينهما، والله المستعان، نعم. المقدم: لو انقطعت أخباره عنهم في هذه الفترة فحصل مثلًا أن تزوجت زوجته غيره أو ....؟\nالشيخ: هذا محل نظر، عاد إذا هي طال عليها الفصل أو المدة في إمكانها أن ترفع أمرها إلى الحاكم الشرعي تطلب النظر في أمرها؛ لأن الغائب المفقود مثل هذا ما يعجل في فسخها منه إلا بعد النظر من الحاكم الشرعي والتأمل، والغيبة تختلف قد تكون غيبته يرجى فيها السلامة، ولا يخشى فيها الهلاك، قد تكون غيبته، يعني: يغلب عليها الهلاك فهو محل تفصيل، لكن ما دام رجع إليها، وهي في عصمته، ولم يتغير شيء، فالحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/13759/حكم-انقطاع-الرجل-عن-اهله-السنة-والسنتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_670/nour_67005.mp3","categories":["غياب وفقدان الزوج"]},{"id":15321,"question":"هذا سؤال بعث به (أبو عمر ط. م. ش) من العراق، محافظة نينوى، يقول: في منطقتنا استشهد أحد الشباب، وجاءت الجثة إلى أهله مشوهة غير واضحة المعالم، ولكن العنوان يدل على اسم الشهيد وبيته ودفنوه في مقبرة القرية، وترك الشهيد زوجة وأطفاله، وبعد تسعة أو عشرة أشهر مضت على استشهاد الشاب جاء أهل الزوجة إلى أخي الشهيد يريدون منه أن يتزوج ابنتهم زوجة الشهيد، فرفض أن يتزوجها، وبعد أيام من هذا الأمر قالوا له: إن لم تتزوجها زوجناها لغيرك، وبقي الأخ في موقف حرج، إما أن يتزوجها، ويحافظ على يتامى أخيه، وإما أن يتركها تتزوج غيره، وعلى أي حال فقد تزوجها من غير رغبة، وبعد مرور سنة من الزواج أنجبت له طفلًا. وبعد أشهر جاءت رسالة من أخيه الذي اعتقدوا بأنه قد استشهد، يقول فيها: أنا باقٍ على قيد الحياة، وإنني أسير في أحد سجون العدو، ويوصي فيها بزوجته وأولاده، فأصيب أخوه بمصيبة عظيمة بسبب زواجه من زوجة أخيه الموجود حيًا يرزق، فعندما يرجع الأسير إلى بلده وأهله بسلام، هل يكون الزواج الثاني باطلًا أم يحق لهم البقاء في بيت الزوجية؟ وإن كان باطلًا فكيف يرجع الزوج الأول إلى زوجته إن كان له حق الرجوع؟ وأخيرًا ما هو حل الشريعة في هذا الأمر؟","title":"حكم من تزوج زوجة أخيه لاعتقاد موته ثم ظهر أنه حي","answer":"الجواب: هذا الأمر يحتاج إلى تثبت، ما دام الشهيد الذي جاء إليهم عليه علامات أنه أخو الشخص، وأنه قتيلهم، وولدهم، وتزوجها على هذا الأمر، وهو أن أخاه قد استشهد، فلا إثم عليه، ولا حرج عليه، لكن متى ثبت يقينًا أن أخاه موجود في السجن، فعليه أن يفارقها حينئذٍ وتبقى زوجة لأخيه، وإن شاءت رفعت الأمر إلى القاضي الشرعي ليفسخها إذا كانت في حاجة للفسخ والمفارقة لسجنه، وعدم وصوله إليها، فهذا شيء يرجع إلى القاضي الشرعي الذي ينظر في أمر المرأة هذه وزوجها؛ لأني أخشى أن يكون هذا الكاتب كاذبًا، وأراد أن يشوش على أخي الشهيد ويزعم أنه فلان.\nالمقدم: الذي كتب الرسالة؟\nالشيخ: الذي كتب الرسالة يخشى أن يكون أيضًا مزورًا كاذبًا، فلا بد من التثبت في الأمور، فإذا سأل المسؤولين في حكومة العراق، أو أرسلوا من ينظر السجناء، أو يختبر السجناء حتى يعرفهم الذين يعرفونه بعد التثبت من ذلك حينئذٍ يفارقها زوجها الجديد -أخوه- وتبقى في عصمة زوجها الأول، ولا حرج على أخيه؛ لأنه لم يتعمد الباطل، إنما أخذها على اعتقاده أن أخاه قد مات، وهكذا اعتقاد أهلها فلا شيء عليهم، والحمد لله، وإن لم يثبت هذا فإنها زوجته ولا يعجل ولا يكتف بمجرد هذا الكتاب الذي كتبه إلا إذا كان معروفًا أنه خطه، خط أخوه، إذا عرف أن هذا خط أخيه، عرفه الشهود العدول أن هذا قلمه، وأنه مؤرخ من جديد، وليس فيه شبهة، لا يخشى أن أحد أخذ خطًا قديمًا أو قلد خطه. المقصود: أنه لا بد من التثبت في الأمور، فإذا تيقن يقينًا أن أخاه موجود، فحينئذٍ يعتزلها، ويكون تزوجها، وهي ذات زوج، ويكون معذورًا، والأحوط أن يطلقها طلقة واحدة خروج من خلاف من قال بصحة الزواج في هذه الحالة، ولو ظهر أنه حي؛ لأنه تزوجها على وجه شرعي باعتقاد أنه مقتول، نعم. المقدم: لكن بعد وصول الخبر إلى أن تتضح الحقيقة هل يعتزل زوجته؟ الشيخ: ما يلزمه الاعتزال؛ لأن الأصل حل النكاح، الأصل أنه زواج شرعي، فلا يلزمه اعتزالها، حتى يتحقق أن أخاه موجود. المقدم: نعم، أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13827/حكم-من-تزوج-زوجة-اخيه-لاعتقاد-موته-ثم-ظهر-انه-حي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_677/nour_67703.mp3","categories":["غياب وفقدان الزوج"]},{"id":15598,"question":"رسالة بعث بها مستمع، رمز إلى اسمه بالحروف (ف. ص. ع) يقول: أنا مغترب عن بلدي منذ أكثر من أربع سنوات، وزوجتي وأطفالي تركتهم عند أهلي، فهل علي إثم في ذلك؟","title":"هل يأثم الزوج بسبب غربته عن زوجته؟","answer":"الجواب: هذا فيه تفصيل: إن كانت الضرورة دعت إلى هذا السفر والغربة، من طلب الرزق، وأنت محتاج إلى ذلك؛ فليس عليك شيء، ولكن ينبغي لك أن تجتهد في جلبهم إليك، ونقلهم إليك إذا تيسر ذلك، فإن لم يتيسر فينبغي لك أن تختصر الغربة، ترجع إليهم في كل ستة أشهر، أو في أقل من ذلك، حسب الطاقة، من أجل تفقد أحوالهم، ومن أجل أيضًا قضاء الوطر من الزوجة، فهذا فيه خير كثير لك وللزوجة جميعًا؛ ولجميع العائلة.  فالوصية ألا تطول الغربة، الوصية أن تجتهد في تقصير الغربة، إلا إذا جلبتهم معك، وتيسر ذلك؛ فهذا أكمل وأحسن، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14134/هل-ياثم-الزوج-بسبب-غربته-عن-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70502.mp3","categories":["غياب وفقدان الزوج"]},{"id":15748,"question":"يقول هذا السائل: ما الحكم في البعد عن الزوجة أكثر من عام؟ وما حقها؟ هل هذا مخالف للسنة؟ مع العلم بأن البعد ليس على ظاهره، ولكن لظروف المعيشة.","title":"حكم غياب الرجل عن امرأته مدة طويلة","answer":"الجواب: ليس في هذا حد محدود، الإنسان يتحرى المدة التي يستطيعها، ولا يضر بها، زوجته، حسب حاجاته، حسب ما يستطيع، يروى عن عمر  «أنه وقت للجنود ستة أشهر» وهذا من باب الاجتهاد.  فالإنسان إذا غاب لعمل إذا استطاع أن كل ستة أشهر أو أربعة أو ثلاثة الأحوال تختلف، فإذا كان يخشى على زوجته يذهب بها معه، أو يعجل، لا يبطئ، يعني: شهر شهرين، ثم يرجع، أو يجعلها في محل مضبوط، عند أهلها، أو عند أهله، مضبوطين. المقصود: يتحرى ما هو الأسلم والأصلح، إن كان بقاؤها وحدها ما فيه خطر عند أهله، أو عند أهلها، فلا بأس، ولكن يجتهد في تعجيل الأوبة، والرجوع إليها، وإن كان ذهابها معه أصلح، واستطاع يذهب بها معه، وهكذا المدة ستة أشهر، أربعة أشهر، ثلاثة أشهر، وحسب ما يستطيع، حسب ما يراه بعيدًا عن الخطر. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14336/حكم-غياب-الرجل-عن-امراته-مدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57509.mp3","categories":["غياب وفقدان الزوج"]},{"id":15973,"question":"السائل من الأردن يقول: ما حكم الشرع في نظركم -سماحة الشيخ- في الابتعاد عن الزوجة أكثر من سنة لظروف الحياة علمًا بأنه يرسل النفقة دائمًا؟ وجزاكم الله خيرًا.","title":"حكم غيبة الرجل عن امرأته فترة طويلة طلبًا للرزق","answer":"الجواب: هذا شيء لا يستطاع تحديده حسب الطاقة، عليه أن يجتهد في قربه منها، وحملها معه أو الرجوع بسرعة من سفره؛ حسب الطاقة، وإذا تأخر من أجل طلب الرزق والعمل فلا حرج عليه إن شاء الله، لكن مهما أمكن أن يجتهد في أن تكون معه حتى يكون أعف له وأعف لها، أو أمكنه أن يرجع بسرعة بحيث لا يطيل الغيبة، يرجع ثم يعود ثم يرجع حتى تكون هذه الاتصالات كافية في العفة له ولها جميعًا. المقصود أن عليه أن يجتهد في حملها معه، أو تقصير المدة بين وقت وآخر حتى تحصل العفة، وتحصل المعاشرة الطيبة من دون مشقة على الجميع. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14588/حكم-غيبة-الرجل-عن-امراته-فترة-طويلة-طلبا-للرزق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57814.mp3","categories":["غياب وفقدان الزوج"]},{"id":16175,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: (عبدالله. ف) الأخ عبدالله يقول في أحد أسئلته: بحكم ظروف العمل، والحياة الاقتصادية، والمعيشة نضطر للغياب عن زوجاتنا سنة، وسنتين، وأكثر، كيف توجهوننا، وما الحكم؟ جزاكم الله خيرًا.الشيخ: أعد.المقدم: يقول: بحكم ظروف العمل، والحياة الاقتصادية، والظروف الصعبة نغيب عن زوجاتنا سنة، وسنتين، وأكثر، كيف توجهوننا؟ جزاكم الله خيرًا.","title":"حكم غياب الزوج عن زوجته مدة طويلة","answer":"الجواب: لا حرج في ذلك عند الضرورة، إذا كانت الضرورة تدعو إلى ذلك؛ فلا حرج في ذلك؛ لأن طلب الرزق الحلال أمر مطلوب، وقد لا يتيسر للإنسان أن تكون المدة قليلة، فإذا اضطر إلى مدة طويلة؛ فلا حرج في ذلك، ولاسيما إذا رضيت الزوجة، وسمحت، أما إذا لم ترض فينبغي أن تحملها معك، أن تكون معك في سفرك؛ لأن ذلك أحصن لفرجك، ولفرجها، وأبرأ للذمة، وأحسن في العاقبة -إن شاء الله- وإلا فقدر أيامًا، أو شهورًا تصطلحان عليها أنت والمرأة، تغيبها، ثم ترجع في طلب الرزق، وحاول لذلك حسب الطاقة. والله يقول: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] ويقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] حاول أن تتفق معها على مدة معلومة تغيبها لطلب الرزق، أو حاول أنك تحملها معك، أو حاول سماحها إذا كنت لا تخشى عليها الفتنة، ولا على نفسك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14843/حكم-غياب-الزوج-عن-زوجته-مدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75015.mp3","categories":["غياب وفقدان الزوج"]},{"id":16596,"question":"يسأل ويقول: إنني أقيم الآن في المملكة، وأغيب عن زوجتي عامًا، أو عامًا ونصف، هل في بعدي عن زوجتي وعن أولادي ضرر؟","title":"نصيحة لمن يطيل الغياب عن زوجته","answer":"الجواب: الوصية والنصيحة ألا تبعد عنهم كثيرًا، وإذا بعدت فراجعهم بين الشهرين، والثلاثة، ولا تهملهم، إلا عند الضرورة القصوى، ولاسيما إذا كانت سامحة، وراضية بذلك. فالمقصود: أن المرأة على خطر في بعد زوجها عنها، ولا سيما في هذا العصر، فنصيحتي لك، ولأمثالك عدم البعد عن الزوجة، وعدم طول الغيبة، بل كن قريبًا منها، ولو بالرزق القليل، فإن ذلك فيه خير عظيم لك، ولأهلك، ولا تحرص على كثرة المال مع الغيبة، والبعد عن أهلك، وتعريض نفسك وأهلك للأخطار، فإن الإنسان على خطر، والنفس أمارة بالسوء، والوقت وقت خطير لظهور الفساد في الأرض، وكثرة من يتعرض للمؤمن في حياته الآن بالشر، فينبغي لك أن تحرص على قربك من أهلك، وعلى عفة فرجك، وعفة نظرك، وسمعك، وعفة أهلك، ولو كان الدخل قليلًا، مادام يقوم بحالك، فإذا غبت فلا تطول الغيبة، بل اكتف بالشهرين، والثلاثة؛ لعل ذلك يكفيك، ويحصل به الخير للجميع لك، ولأهلك، رزق الله الجميع التوفيق، والهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15321/نصيحة-لمن-يطيل-الغياب-عن-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81704.mp3","categories":["نصائح وتوجيهات","غياب وفقدان الزوج"]},{"id":16966,"question":"رسالة من أحد الإخوة المستمعين يقول: أنا رجل مغترب غبت عن زوجتي ما يقرب من أربعة عشر عامًا، فما حكم الإسلام في تصرفي هذا؟ وهل أنا آثم، وجهوني إلى الصواب؟ جزاكم الله خيرًا.","title":"هل يأثم الرجل إذا غاب عن أهله عدة سنوات؟","answer":"الجواب: إذا كانت الزوجة سامحة بذلك، راضية بذلك فلست بآثم، وأنت كذلك إذا كنت لم تستعن بها على معاصي الله فلست بآثم، أما إذا كنت استعملت هذه المدة في معاصي الله في الزنا والفواحش؛ فأنت آثم بما فعلت من المعاصي، والمرأة سليمة من ذلك إذا كانت سامحة. فأما إن كانت لم ترض؛ فعليك أن تستسمحها، وأن تتوب إلى الله من هذه المدة الطويلة، أما إذا كانت راضية فالحمد لله، وجزاها الله خيرًا.  أما أنت فالواجب عليك في المستقبل أن تستعين بالله، وأن تجتهد في القيام بحقها، وأن تكون أعمالك في المكان الذي فيه زوجتك؛ حتى تجمع بين المصلحتين، إما أن تنقلها إلى عملك، وإما أن تنتقل إليها في محلها وبلدها، حتى يجمع الله بينكما على خير، مع الاستقامة على طاعة الله ورسوله، ومع الحذر من محارم الله. وإذا كان البلد التي أنت فيها فيها خطر؛ فانتقل إليها إلى البلد السليمة أنت وزوجتك، ولا تنتقل إلى بلد فيها خطر من تعاطي ما حرم الله، أو ما هو أعظم من ذلك من الكفر بالله، احذر الانتقال إلى بلاد الكفر والضلال والبدع، واحرص على أن تكون في بلد سليمة بعيدة عن الخطر، أنت وزوجتك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15752/هل-ياثم-الرجل-اذا-غاب-عن-اهله-عدة-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_766/nour_76603.mp3","categories":["غياب وفقدان الزوج"]},{"id":17373,"question":"هذا السائل الذي رمز لاسمه بـ (ع. ل. ب) يقول: أريد أن أفيدكم بأنني مقيم بالمملكة منذ أربع سنوات، ولم أسافر، ولي زوجة، وبنات، وهم في بلدي، والسبب في ذلك بأنني أريد أن أكسب لقمة العيش في هذا البلد المبارك، وأعمل عاملًا بالبقالة بالراتب، وأرسل لهم شهريًا، هل آثم على تركي لهم هذه المدة؟","title":"ما حكم الغياب عن الأهل لمدة طويلة؟","answer":"الجواب: يخشى عليك من الإثم؛ لأن المدة طويلة، فالذي أرى أن الواجب عليك أن تذهب إليهم بين وقت وآخر، كان عمر  وقَّت ستة أشهر للمجاهدين والغائبين، فأنت يا أخي! اذهب إليهم كل ستة أشهر، أو كل أربعة أشهر، أو نحو ذلك، أو أحضرهم لديك، أما أن تتركهم هذه المدة الطويلة هذا فيه خطر كبير عليهم، وعليك أيضًا. فالمشروع لك ترك هذا الأمر، وأن تحضرهم لديك إذا أمكن، أو تذهب إليهم كل ستة أشهر.. كل أربعة أشهر.. كل خمسة أشهر، لا تطول المدة، تبقى عندهم شهرًا.. شهرين ثم ترجع لطلب الرزق. فالحاصل: أن الواجب عليك العناية بهذا الأمر، والحذر من مدة طويلة قد توقعهم في الفاحشة، أو توقعك أنت في الفاحشة، ولا حول ولا قوة إلا بالله. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16220/ما-حكم-الغياب-عن-الاهل-لمدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77006.mp3","categories":["نصائح وتوجيهات","غياب وفقدان الزوج"]},{"id":18110,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: إن زوجها غاب عنها أكثر من سبع سنوات، وحتى كتابة هذه الرسالة لم يصل إليهم، وترجو من سماحتكم توجيه المغتربين عن أزواجهم جزاكم الله خيرًا.","title":"نصيحة للمغتربين بعدم تطويل الغياب عن أهاليهم","answer":"الجواب: نعم، إني أنصح المغتربين جميعًا في أي مكان أن لا يطولوا السفر عن أزواجهم، وأن يحرصوا على سرعة الإياب؛ لأن بقاء المرأة بدون زوج فيه خطر عظيم على عرضها وعلى زوجها وعلى أولادها وعلى المجتمع كله، فالمشروع للمؤمن أن يراعي هذا الأمر وأن لا يطول الغربة بالنسبة إلى زوجته وأولاده بل تكون الغربة قصيرة ولاسيما في هذا العصر الذي كثرت فيه الشرور، وقل فيه العلم، وقلت فيه التقوى، وغلب فيه الجهل والشر والفساد. فالمؤمن يتقي الله في أهله ولا يطول، أو ينقلهم معه إلى محله الذي هو فيه ولا يتركهم وحدهم، إما أن ينقلهم إذا كان المحل الذي هو فيه آمن وليس فيه خطر وإلا فليعجل الغربة ولا يتأخر، وليعمل في بلد حوله وفي بلدهم حتى يمكن له الوصول إليهم بين وقت وآخر من دون مشقة ولا خطر. فالحاصل أن الواجب على الأزواج أن يتقوا الله في أزواجهم وأن يحذروا إهمالهم فإن في ذلك خطرًا عظيمًا على الجميع. وقد كان عمر  يكتب إلى الجنود أن لا يتأخروا أكثر من ستة أشهر عن أزواجهم؛ لما علم  من الخطر في ذلك، فكيف لو رأى الحال ورأى الزمان اليوم؟ فالذي ينبغي أن لا يطول ولا ستة أشهر بل شهرين ثلاثة أقل من ذلك، وإذا أمكن أن يأتي إليهم بين وقت وآخر في أقصر وقت ويرجع إلى عمله إذا أمكن ذلك فهذا هو الأحوط وهو الذي ينبغي، وإذا أمكن أن ينقلهم إلى محله إذا كان نقلهم ليس فيه خطر فهو أولى وأحوط أيضاً. فالحاصل أنه ينبغي للزوج أن لا يطول الغربة وأن يسرع الإياب إلى أهله حتى لا تقع المصيبة التي يخشى منها ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/17145/نصيحة-للمغتربين-بعدم-تطويل-الغياب-عن-اهاليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_904/nour_90410.mp3","categories":["غياب وفقدان الزوج"]},{"id":18393,"question":"أخ لنا من جمهورية مصر العربية -رمضان محمد عمار- يقول: لي مدة ثلاث سنوات وأنا الآن داخل في الرابعة غائب عن زوجتي وعن أطفالي لكني كفيتهم مئونة البيت والمدارس، هل أنا مخطئ في غيابي عن زوجتي هذه المدة؟ أرجو التوجيه جزاكم الله خيرًا.","title":"حكم غياب الرجل عن أهله مدة طويلة","answer":"الجواب: لم يرد فيما نعلم في الشرع المطهر تحديد للغيبة للزوج، وقد روي عن عمر رضي الله عنه أنه حدد للجنود ستة أشهر من باب الاجتهاد والتحري للخير، فإذا كنت أيها السائل غبت في طلب الرزق الحلال وشغلت عن المجيء إلى أهلك لأمور ألجأتك إلى طول الغيبة فنرجو أن لا يكون عليك شيء ما دمت قد قمت بحقهم وأنفقت عليهم، ولكن ينبغي لك أن لا تطيل الغربة، وأن تلاحظ حاجة الزوجة وحاجة الأولاد إلى مجيئك، وإلى قضاء وطرك من أهلك، وإلى عفة أهلك، وإلى ملاحظة أولادك وتأديبهم وتربيتهم التربية الإسلامية، إلى غير ذلك من مصالحهم. فينبغي لك أن تلاحظ المدة المناسبة التي ترجع فيها إليهم، ثم تعود إلى عملك إذا لم يتيسر لك عمل في محل أهلك، ولم يتيسر نقلهم معك في محل مناسب آمن، فأنت على كل حال تنظر ما هو الأصلح في عفة أهلك وصلاح أولادك من جهة النقل معك، أو من جهة المجيء إليهم في وقت ليس بالطويل كثلاثة أشهر، شهرين، أربعة، خمسة، على حسب ما يتيسر لك ما دمت في طلب الرزق، وطلب الحلال والحاجة إلى ذلك، فليس في هذا وقت مقدر فيما نعلم من جهة الكتاب والسنة، واجتهاد عمر  في ذلك له وجاهته. وقد تحتاج الزوجة إلى أقل من الستة الأشهر، قد تكون في محل خطير يضرها غيبتك ستة أشهر، وقد تكون في محل آمن ويكون عندها من العقل والدين والإيمان ما يطمئنك لو أطلت أكثر من ستة أشهر، فالحال تختلف، والنبي ﷺ قال: عليكم بسنتي وسنة الخلفاء الراشدين المهديين من بعدي، وعمر منهم، بل هو أفضلهم بعد الصديق، فعليك أن تلاحظ ما هو الأصلح وما هو الأقرب إلى سلامة أهلك وأولادك لمراعاة الستة الأشهر أو ما هو أقل منها، أو ما هو فوقها على حسب قدرتك وعلى حسب حال أهلك، والطمأنينة إلى سلامة الأهل والأولاد مما يضرهم وعدم ذلك، فهو محل اجتهاد ومحل نظر منك، والواجب عليك أن تعمل ما هو الأصلح، وما هو الأحوط وما هو الأقرب إلى سلامة أهلك وأولادك، والله المستعان، نعم. المقدم: بارك الله فيكم. بالنسبة لعصرنا وما فيه من الفتن والمغريات تنصحون بتبني رأي عمر رضي الله عنه؟ الشيخ: بل أنصح بأقل من ذلك، أنصح بأن تكون المدة أقل من ستة أشهر، وأن يلاحظ الزوج أن لا تطول الغيبة، وأن تكون الغيبة قصيرة جدًا مهما أمكن، أو يبقى عند أهله ولو بالمشقة، أو ينقلهم معه؛ لأن الأخطار كثيرة والفتن كثيرة، والسلامة الآن قليلة في غالب الأماكن، فينبغي له أن يلاحظ ذلك وأن يحذر أن يقع أهله فيما لا ينبغي بسبب غيبته، والله المستعان. نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17477/حكم-غياب-الرجل-عن-اهله-مدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_863/nour_86303.mp3","categories":["غياب وفقدان الزوج"]},{"id":18895,"question":"رسالة وصلت إلى البرنامج من المستمع حسين حسن جاد الله من السودان، أخونا له سؤالان، في سؤاله الأول يقول: إن عمره ثمان وعشرون سنة، وقد غاب عن زوجته أكثر من عام ونصف، ويسأل هل ذلك جائز؟","title":"حكم غياب الرجل عن امرأته مدة طويلة","answer":"الجواب: هذا فيه تفصيل، أما إذا كنت عاجزًا، ولم تستطع العودة إليها؛ لأنك محبوس، أو لم تستطع قيمة التذكرة، أو قيمة الأجرة للسيارة، المقصود إذا كنت عاجزًا فهذا لا شيء فيه؛ لأنك عاجز، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. أما إذا كنت غبت لحاجات خاصة تستطيع أن ترجع إليها، وتقوم بحالها، وتشرف على شؤونها، ثم ترجع إلى عملك بين وقت وآخر كشهرين ثلاثة أربعة، هكذا ينبغي للمؤمن لا يطيل السفر عن أهله، ولا سيما في هذا العصر الذي هو من أخطر العصور، فالمؤمن يلاحظ هذه الأشياء، فلا يطيل السفر، ولا يهمل حاجته التي هو في حاجة إليها مثل طلب العلم، ومثل طلب كسب الحلال؛ لأن بلده ليس فيها حاجته، ليس فيها طلب العلم، ليس فيها كسب يقوم بحاله. وجاء عن عمر  أنه كان وقت للجنود ستة أشهر في الغيبة عن أهليهم، ثم يرجعون ويذهب غيرهم.  فالحاصل: أن هذا يختلف باختلاف الأحوال، وباختلاف نفس الشخص، فأنت لا تطيل الغربة، احرص على عدم طول الغربة، ولو شهرين ثلاثة يكفي؛ لأن الأحوال تختلف، فقد تكون زوجتك في محل لا يؤمن عليها، وأنت لاحظ حالها، ولاحظ الحرص على سلامتها، وبعدها عما يخشى منه من خطر العرض، وغير ذلك. فالحاصل: أنت تلاحظ الشيء الذي يبرئ ذمتك، وينفع زوجتك، لا من جهة عرضها ودينها، ولا من جهة حاجتها فيما يتعلق بأكلها وشربها وكسوتها، ونحو ذلك، وأنت أعلم بنفسك وأبصر، فاحرص على الشيء الذي ينفعك وينفعها ويبرئ ذمتك لا من جهة المدة، ولا من جهة النفقة، والله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا، إنما كما تفضلتم سماحة الشيخ في حال السعة لا يجوز للإنسان أن يتأخر أكثر من ستة أشهر؟ الشيخ: هكذا وقت عمر، وهو توقيت له أهميته، وهو توقيت جيد، ولكن في هذا الوقت الستة طويلة أيضًا، في هذا الوقت الستة طويلة، ولا سيما في غالب الأمصار، وغالب القرى الخطر كبير، كونه لا يطيل حتى الستة، شهرين ثلاثة أربعة مهما أمكن ليكون قريبًا منها فهو أولى وأحرى. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18037/حكم-غياب-الرجل-عن-امراته-مدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_923/nour_92305.mp3","categories":["غياب وفقدان الزوج"]},{"id":19136,"question":"رسالة وصلت إلى البرنامج من العراق وباعثها أحد الإخوة يقول: محسن عبد العزيز عبد الواحد من جمهورية مصر العربية، أخونا يقول: إنه يعمل سائق سيارة أجرة، ويغيب عن زوجته أكثر من عامين، ويسأل عن حكم ذلك، جزاكم الله خيرًا.","title":"حكم غياب الزوج عن زوجته لمدة طويلة","answer":"الجواب: ينبغي له أن يتقي الله فيها، ينبغي له أن يتقي الله في زوجته، وأن لا يغيب عنها المدة الطويلة، بل يحاسب نفسه، ويأتيها بين وقت وآخر حسب الطاقة، ولا يتساهل في هذا الأمر؛ فإن هذا قد يفضي إلى انحرافها ووقوعها فيما حرم الله؛ لأنها مدة طويلة، والزوجة لها حق عظيم، الله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، وليس من المعروف أن يهجرها هذه المدة الطويلة، ولكن يجاهد نفسه حتى يأتيها بين وقت وآخر، شهرين ثلاثة أربعة ستة على الأكثر كما يروى عن عمر  أنه وقت للجنود ستة أشهر. فالحاصل أن هذا تختلف فيه الأحوال، والوقت الآن غير وقت عمر أيضًا، وقت عمر كان أصلح، وكان الناس فيه على خير وعلى خوف من الله أكثر من وقتنا، وقتنا هذا فيه الانحراف الكثير، والخطر الكثير، وكثرة الفواحش، فينبغي للزوج أن ينظر إلى هذه الأمور، وأن لا يتساهل في حق زوجته، بل يكون عمله قريبًا منها حتى يزورها بين وقت وآخر، أو ينقلها معه في عمله الذي هو فيه حتى يصونها ويصون عرضه وعرضها، وعليه أن يتقي الله في ذلك، هو مسئول عنها، فعليه أن يتقي الله في شأنها، وألا يهجرها المدة الطويلة من أجل كسب الدنيا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18353/حكم-غياب-الزوج-عن-زوجته-لمدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_886/nour_88612.mp3","categories":["غياب وفقدان الزوج"]},{"id":19630,"question":"يقول: كم المدة المسموح فيها في الشرع عند مفارقة الزوجة إذا ذهبت للعمل، هل إذا أطلت المدة المحدودة دخلت في الإثم؟","title":"المدة المسموح بها في الشرع لمفارقة الزوجة لأجل العمل","answer":"الجواب: الواجب عليك المعاشرة بالمعروف، الله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ[النساء:19] فإذا شغلت عن جماعها، أو المبيت معها في عمل فلا حرج، لكن إذا كان معك زوجة ثانية فلا بد من العدل، أما شغلك عنها فليس له حد محدود إذا كنت في عمل، واشتغلت في بعض الأيام؛ فلا حرج عليك. نعم.","link":"https://binbaz.org.sa/fatwas/18895/المدة-المسموح-بها-في-الشرع-لمفارقة-الزوجة-لاجل-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94826.mp3","categories":["غياب وفقدان الزوج"]}]
